"use strict";(self.webpackChunkbed_mega_textbook=self.webpackChunkbed_mega_textbook||[]).push([[2776],{7410(e,n,i){i.r(n),i.d(n,{assets:()=>c,contentTitle:()=>d,default:()=>f,frontMatter:()=>h,metadata:()=>t,toc:()=>l});const t=JSON.parse('{"id":"semester-1/efmp-302/unit-03/topic-01","title":"Topic 3.1 - What \\"an effective teacher\\" actually means","description":"Competing definitions of teacher effectiveness, why they disagree, and the components used to evaluate it - within-classroom processes and the factors beyond them.","source":"@site/docs/semester-1/efmp-302/unit-03/topic-01.mdx","sourceDirName":"semester-1/efmp-302/unit-03","slug":"/semester-1/efmp-302/unit-03/topic-01","permalink":"/semester-1/efmp-302/unit-03/topic-01","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Topic 3.1 - What \\"an effective teacher\\" actually means","description":"Competing definitions of teacher effectiveness, why they disagree, and the components used to evaluate it - within-classroom processes and the factors beyond them.","course_code":"EFMP-302","unit_no":3,"topic_no":1,"topic_label":"3.1","clo_refs":["SLO:EFMP-302-3-1"],"blooms_summary":"Understand that teacher effectiveness has competing definitions and that each serves the purpose of whoever is measuring; remember the components used to evaluate it; apply the components to judge a described teacher, and analyse why two evaluators can reach opposite verdicts on the same evidence.","est_reading_minutes":23,"translation_status":"draft"},"sidebar":"textbook","previous":{"title":"Becoming an Effective Teacher","permalink":"/semester-1/efmp-302/unit-03/"},"next":{"title":"Topic 3.2 - The qualities an effective teacher brings","permalink":"/semester-1/efmp-302/unit-03/topic-02"}}');var o=i(4848),a=i(8453),r=i(6606),s=i(6462);const h={title:'Topic 3.1 - What "an effective teacher" actually means',description:"Competing definitions of teacher effectiveness, why they disagree, and the components used to evaluate it - within-classroom processes and the factors beyond them.",course_code:"EFMP-302",unit_no:3,topic_no:1,topic_label:"3.1",clo_refs:["SLO:EFMP-302-3-1"],blooms_summary:"Understand that teacher effectiveness has competing definitions and that each serves the purpose of whoever is measuring; remember the components used to evaluate it; apply the components to judge a described teacher, and analyse why two evaluators can reach opposite verdicts on the same evidence.",est_reading_minutes:23,translation_status:"draft"},d='Topic 3.1 - What "an effective teacher" actually means',c={},l=[{value:"A real classroom situation",id:"a-real-classroom-situation",level:2},{value:"Explanation",id:"explanation",level:2},{value:"Redefining effective teaching and the effective teacher",id:"redefining-effective-teaching-and-the-effective-teacher",level:3},{value:"The components of teacher effectiveness, and what each can and cannot show",id:"the-components-of-teacher-effectiveness-and-what-each-can-and-cannot-show",level:3},{value:"Activity: What did you count?",id:"activity-what-did-you-count",level:2},{value:"Check your understanding",id:"check-your-understanding",level:2},{value:"Summary",id:"summary",level:2},{value:"Self-assessment checklist",id:"self-assessment-checklist",level:2},{value:"Try this at your practicum school",id:"try-this-at-your-practicum-school",level:2},{value:"Summative task",id:"summative-task",level:2},{value:"Further reading",id:"further-reading",level:2}];function u(e){const n={a:"a",blockquote:"blockquote",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",input:"input",li:"li",ol:"ol",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,a.R)(),...e.components},{Figure:i}=n;return i||function(e,n){throw new Error("Expected "+(n?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Figure",!0),(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(r.A,{}),"\n",(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"topic-31---what-an-effective-teacher-actually-means",children:'Topic 3.1 - What "an effective teacher" actually means'})}),"\n",(0,o.jsx)(n.h2,{id:"a-real-classroom-situation",children:"A real classroom situation"}),"\n",(0,o.jsx)(i,{id:"fig-U3-1",kind:"table",width:"900",height:"400",src:"/img/figures/efmp-302/unit-03/fig-U3-1.svg",alt:"Table comparing three definitions of teacher effectiveness - achievement gain, observed practice and breadth of learner outcomes - by what each counts, captures, misses, and who uses it."}),"\n",(0,o.jsx)(n.p,{children:"Two teachers take Class 9 mathematics in neighbouring rooms of the same government school in\nLarkana. At the end of the year their board results are almost identical."}),"\n",(0,o.jsx)(n.p,{children:"Mr Junaid's room is silent. He works through the past five years of board papers, question by\nquestion. Pupils copy his worked solutions and reproduce them. Anyone who asks a question that\nis not on the syllabus is told there is no time. His pupils pass."}),"\n",(0,o.jsx)(n.p,{children:"Miss Shazia's room is noisier. She spends the first term on why the methods work, which costs\nher three weeks she never gets back, and she pushes pupils to attempt problems before she has\nshown them how. Two of her weakest pupils fail the mock badly and recover by March. Her pupils\npass at the same rate as Mr Junaid's."}),"\n",(0,o.jsx)(n.p,{children:"Which of them is the effective teacher? The honest answer is that it depends entirely on what\nyou decided to count before you walked in, and this topic is about taking that decision\nseriously rather than pretending it has already been made for you."}),"\n",(0,o.jsx)(n.h2,{id:"explanation",children:"Explanation"}),"\n",(0,o.jsx)(n.h3,{id:"redefining-effective-teaching-and-the-effective-teacher",children:"Redefining effective teaching and the effective teacher"}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(s.A,{term:"Teacher Effectiveness",children:"Teacher effectiveness"})," is usually defined as the\neffect a teacher has on what their pupils learn. That sentence sounds settled and is not, because\neverything depends on which effects you count and how you detect them."]}),"\n",(0,o.jsx)(n.p,{children:"Goe, Bell and Little (2008) report that there is no generally agreed method for evaluating\nteacher effectiveness. Grouping what they and others describe, the definitions in use fall into\nthree recognisable families. The grouping below is this book's, offered as a way to hold the\nfield in mind rather than as their taxonomy:"}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Effectiveness as achievement gain."})," The teacher's effect is the improvement in pupils' measured\nattainment over a year, ideally compared against what similar pupils elsewhere achieved. It has\nthe great merit of being about learning rather than about the teacher's manner. Its weakness is\nthat it counts only what the test tests. Mr Junaid does extremely well on this definition."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Effectiveness as observed practice."})," The teacher's effect is inferred from what they are seen\nto do: how they explain, question, respond, manage time. It captures things a test cannot, and it\nis what most classroom observation instruments measure. Its weakness is that it can reward a\nperformance. A lesson can look excellent and teach nobody anything, and observers are not immune\nto being impressed."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Effectiveness as breadth of learner outcomes."})," The teacher's effect includes attainment but\nalso what else changed: whether pupils became more willing to attempt hard problems, whether\nattendance held, whether a pupil who intended to leave stayed. Miss Shazia looks strongest here.\nIts weakness is that these outcomes are genuinely hard to measure, and what is hard to measure\nis easy to assert."]}),"\n",(0,o.jsx)(n.p,{children:"Taylor and Thion (2023) put a sharper point, though note what they studied: reviewing the\nresearch literature on teaching effectiveness, they found many papers using inaccurate or merely\nimplied definitions, so that the definition stated and the thing actually measured came apart.\nTheir subject is research, not school appraisal. The same gap is easy to recognise in a school,\nwhere an institution may say it values deep understanding and appraise its teachers on examination\nresults, and the appraisal is what teachers respond to. That extension is a reasonable inference\nrather than their finding."}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"So what should a trainee conclude?"})," Not that effectiveness is meaningless. The three families\nagree on more than they disagree about. What follows is narrower and more useful: whenever\nsomeone calls a teacher effective, ask what was counted. And when you are evaluated, find out\nwhich definition is in force before you plan your year around the wrong one."]}),"\n",(0,o.jsxs)(n.p,{children:["This dismantles a misconception worth naming: ",(0,o.jsx)(n.em,{children:"an effective teacher is one whose class gets high\nmarks"}),". That is one definition, not the definition, and it is the one most vulnerable to being\nachieved in ways nobody wants. A teacher can raise marks by narrowing teaching to the test,\nwhich raises the measure and lowers the learning it was supposed to indicate."]}),"\n",(0,o.jsx)(n.h3,{id:"the-components-of-teacher-effectiveness-and-what-each-can-and-cannot-show",children:"The components of teacher effectiveness, and what each can and cannot show"}),"\n",(0,o.jsx)(i,{id:"fig-U3-2",kind:"concept-map",width:"900",height:"460",src:"/img/figures/efmp-302/unit-03/fig-U3-2.svg",alt:"Concept map of teacher effectiveness branching into within-classroom processes and factors beyond the classroom, each leaf noting how it is evidenced."}),"\n",(0,o.jsx)(n.p,{children:"Rather than one definition, it is more workable to hold a set of components, each of which can be\nobserved and none of which is sufficient alone. The figure above groups them in the way the\nresearch literature tends to: what happens inside the room, and what happens outside it."}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"Within-classroom processes"})}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.em,{children:"Subject and pedagogical knowledge."})," Knowing the content, and knowing how that particular\ncontent is learned and misunderstood. The second is not implied by the first, which is why a\nbrilliant mathematician can teach mathematics badly."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.em,{children:"Planning and structure."})," Whether a lesson has a destination, and whether the parts serve it."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.em,{children:"Explanation and questioning."})," Whether ideas are made available, and whether questions\ndiscover what pupils think or merely check that someone can say the right words."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.em,{children:"Use of assessment."})," Whether the teacher finds out what pupils have understood and then does\nsomething different because of it. A teacher who tests frequently and teaches identically\nafterwards is not using assessment."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.em,{children:"Classroom climate and management."})," Whether the room is a place where a pupil can risk being\nwrong. Unit 2's account of trust is this component seen from the ethical side."]}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"Beyond the classroom"})}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.em,{children:"Contribution to colleagues."})," Whether the teacher's practice improves anyone else's."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.em,{children:"Relationships with parents and community."})," Covered in Topic 3.3."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.em,{children:"Professional learning."})," Whether the teacher is still changing. Covered in Topic 3.5."]}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:"Two cautions about using components at all."}),"\n",(0,o.jsxs)(n.p,{children:["First, ",(0,o.jsx)(n.strong,{children:"components are evidence, not a score"}),". Adding them up produces a number that feels\nobjective and hides every judgement that went into it. Goe and colleagues are explicit that\ndifferent components are appropriate for different purposes, and that an instrument built for\nprofessional development should not be reused for high-stakes appraisal."]}),"\n",(0,o.jsxs)(n.p,{children:["Second, ",(0,o.jsx)(n.strong,{children:"the components interact"}),". Strong subject knowledge with a hostile climate produces\nless learning than moderate subject knowledge with a safe one, because pupils in the second room\nwill admit what they do not understand. Reading the list as independent boxes to tick misses\nthe thing that actually makes a classroom work."]}),"\n",(0,o.jsx)(n.p,{children:"Return to Mr Junaid and Miss Shazia with the components in hand and the picture sharpens. Mr\nJunaid is strong on structure and weak on questioning and assessment use, because nothing he does\ndiscovers what pupils think. Miss Shazia is strong on climate, questioning and assessment use, and\npaid three weeks for it. Neither is simply better. But only one of them could tell you what their\npupils misunderstand, and that is the difference that compounds over a career."}),"\n",(0,o.jsx)(n.h2,{id:"activity-what-did-you-count",children:"Activity: What did you count?"}),"\n",(0,o.jsx)(n.p,{children:"Work in groups of three. Each group takes one of the three definitions from the figure at the top\nof this topic: achievement gain, observed practice, or breadth of learner outcomes."}),"\n",(0,o.jsx)(n.p,{children:"From your definition alone, write the appraisal you would give Mr Junaid and the appraisal you\nwould give Miss Shazia. Be specific: state what evidence you would collect and what verdict it\nsupports."}),"\n",(0,o.jsx)(n.p,{children:"Then hear all three groups in turn. Two questions for the class afterwards. Which teacher's\nappraisal changed most between definitions, and why? And which definition would you want applied\nto you in your first year of teaching, given what you would be able to demonstrate?"}),"\n",(0,o.jsx)(n.p,{children:"Allow 25 minutes."}),"\n",(0,o.jsx)(n.h2,{id:"check-your-understanding",children:"Check your understanding"}),"\n",(0,o.jsxs)(n.ol,{children:["\n",(0,o.jsxs)(n.li,{children:["State three competing definitions of teacher effectiveness and, for each, one thing it\ncaptures well. ",(0,o.jsx)(n.em,{children:"(Remember)"})]}),"\n",(0,o.jsxs)(n.li,{children:["Explain why a teacher can be judged effective on one definition and ineffective on another\nusing the same evidence. ",(0,o.jsx)(n.em,{children:"(Understand)"})]}),"\n",(0,o.jsxs)(n.li,{children:["Distinguish within-classroom processes from factors beyond the classroom, giving two examples\nof each. ",(0,o.jsx)(n.em,{children:"(Remember)"})]}),"\n",(0,o.jsxs)(n.li,{children:["A teacher tests their class every fortnight and teaches the next unit identically regardless\nof the results. Which component are they failing, and why does frequent testing not rescue it?\n",(0,o.jsx)(n.em,{children:"(Apply)"})]}),"\n",(0,o.jsxs)(n.li,{children:["Explain why adding the components into a single score is a worse instrument than holding them\nseparately. ",(0,o.jsx)(n.em,{children:"(Analyze)"})]}),"\n"]}),"\n",(0,o.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,o.jsx)(n.p,{children:"Teacher effectiveness means the effect a teacher has on pupils' learning, but the definitions in\nuse disagree about which effects count. Achievement gain counts what the test tests; observed\npractice counts what an observer can see and can be satisfied by performance; breadth of learner\noutcomes counts more of what matters and measures it less reliably. Institutions frequently state\none definition and appraise against another."}),"\n",(0,o.jsx)(n.p,{children:"More workable than a definition is a set of components: subject and pedagogical knowledge,\nplanning, explanation and questioning, use of assessment, and classroom climate within the room;\ncontribution to colleagues, relationships beyond it, and continued professional learning outside.\nThe components are evidence rather than a score, they are chosen for a purpose, and they\ninteract, so a strong component can be cancelled by a weak one."}),"\n",(0,o.jsx)(n.h2,{id:"self-assessment-checklist",children:"Self-assessment checklist"}),"\n",(0,o.jsxs)(n.ul,{className:"contains-task-list",children:["\n",(0,o.jsxs)(n.li,{className:"task-list-item",children:[(0,o.jsx)(n.input,{type:"checkbox",disabled:!0})," ","I can state three competing definitions of teacher effectiveness and what each misses."]}),"\n",(0,o.jsxs)(n.li,{className:"task-list-item",children:[(0,o.jsx)(n.input,{type:"checkbox",disabled:!0})," ","I can explain why the definition an institution states and the measure it uses often differ."]}),"\n",(0,o.jsxs)(n.li,{className:"task-list-item",children:[(0,o.jsx)(n.input,{type:"checkbox",disabled:!0})," ","I can name the components of teacher effectiveness and sort them into within-classroom and\nbeyond-classroom."]}),"\n",(0,o.jsxs)(n.li,{className:"task-list-item",children:[(0,o.jsx)(n.input,{type:"checkbox",disabled:!0})," ","I can judge a described teacher against the components rather than by overall impression."]}),"\n",(0,o.jsxs)(n.li,{className:"task-list-item",children:[(0,o.jsx)(n.input,{type:"checkbox",disabled:!0})," ","I can explain why using assessment means changing what you do next, not testing more often."]}),"\n"]}),"\n",(0,o.jsx)(n.h2,{id:"try-this-at-your-practicum-school",children:"Try this at your practicum school"}),"\n",(0,o.jsx)(n.p,{children:"Find out how teachers in your practicum school are actually appraised. Ask your mentor what is\nlooked at, who looks at it, and how often."}),"\n",(0,o.jsx)(n.p,{children:"Then compare what you are told against the three definitions in this topic. Write half a page\nidentifying which definition the school's appraisal is closest to, what that definition rewards,\nand one thing a teacher in that school could do to score well without teaching better. That last\npart is not cynicism; it is the standard test of whether a measure is robust."}),"\n",(0,o.jsx)(n.h2,{id:"summative-task",children:"Summative task"}),"\n",(0,o.jsx)(n.p,{children:"Write 400 to 450 words."}),"\n",(0,o.jsxs)(n.blockquote,{children:["\n",(0,o.jsx)(n.p,{children:"Mr Junaid and Miss Shazia produced the same board results. Judge them both against the\ncomponents of teacher effectiveness and reach a defensible verdict."}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:"Your answer must use at least four named components, cite specific evidence from the vignette\nrather than impressions, state clearly what evidence you do not have and would need, and reach a\nverdict rather than concluding that both have strengths."}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"Mini-rubric"})}),"\n",(0,o.jsxs)(n.table,{children:[(0,o.jsx)(n.thead,{children:(0,o.jsxs)(n.tr,{children:[(0,o.jsx)(n.th,{children:"Criterion"}),(0,o.jsx)(n.th,{children:"What a strong response does"})]})}),(0,o.jsxs)(n.tbody,{children:[(0,o.jsxs)(n.tr,{children:[(0,o.jsx)(n.td,{children:"Use of components (Apply)"}),(0,o.jsx)(n.td,{children:"Names at least four components and applies each to both teachers, not just the convenient ones"})]}),(0,o.jsxs)(n.tr,{children:[(0,o.jsx)(n.td,{children:"Evidence discipline"}),(0,o.jsx)(n.td,{children:"Distinguishes what the vignette states from what the writer is inferring"})]}),(0,o.jsxs)(n.tr,{children:[(0,o.jsx)(n.td,{children:(0,o.jsx)(n.strong,{children:"Reasoned verdict (Evaluate)"})}),(0,o.jsx)(n.td,{children:(0,o.jsx)(n.strong,{children:'Reaches a verdict and defends the criterion it rests on, rather than retreating to "both have strengths"'})})]}),(0,o.jsxs)(n.tr,{children:[(0,o.jsx)(n.td,{children:"Recognition of limits"}),(0,o.jsx)(n.td,{children:"States what further evidence would change the verdict and why"})]})]})]}),"\n",(0,o.jsx)(n.h2,{id:"further-reading",children:"Further reading"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:["Goe, L., Bell, C., & Little, O. (2008). ",(0,o.jsx)(n.em,{children:"Approaches to evaluating teacher effectiveness: A\nresearch synthesis"}),". National Comprehensive Center for Teacher Quality.\n",(0,o.jsx)(n.a,{href:"https://files.eric.ed.gov/fulltext/ED521228.pdf",children:"https://files.eric.ed.gov/fulltext/ED521228.pdf"})]}),"\n",(0,o.jsxs)(n.li,{children:["Taylor, S., & Thion, S. (2023). How has teaching effectiveness been conceptualized? Questioning\nthe consistency between definition and measure. ",(0,o.jsx)(n.em,{children:"Frontiers in Education, 8"}),".\n",(0,o.jsx)(n.a,{href:"https://doi.org/10.3389/feduc.2023.1253622",children:"https://doi.org/10.3389/feduc.2023.1253622"})]}),"\n"]})]})}function f(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(u,{...e})}):u(e)}},6462(e,n,i){i.d(n,{A:()=>a});i(6540);const t=JSON.parse('[{"term":"Educational Psychology","definition_en":"The study of how people learn in educational settings, and how teaching can be organised to help learning.","definition_ur":"\u0627\u0633 \u0628\u0627\u062a \u06a9\u0627 \u0645\u0637\u0627\u0644\u0639\u06c1 \u06a9\u06c1 \u0644\u0648\u06af \u062a\u0639\u0644\u06cc\u0645\u06cc \u0645\u0627\u062d\u0648\u0644 \u0645\u06cc\u06ba \u06a9\u06cc\u0633\u06d2 \u0633\u06cc\u06a9\u06be\u062a\u06d2 \u06c1\u06cc\u06ba\u060c \u0627\u0648\u0631 \u062a\u062f\u0631\u06cc\u0633 \u06a9\u0648 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u0645\u06cc\u06ba \u0645\u062f\u062f \u06a9\u06d2 \u0644\u06cc\u06d2 \u06a9\u06cc\u0633\u06d2 \u062a\u0631\u062a\u06cc\u0628 \u062f\u06cc\u0627 \u062c\u0627 \u0633\u06a9\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Cognition","definition_en":"The mental processes involved in gaining knowledge and understanding - such as attention, memory, and reasoning.","definition_ur":"\u0639\u0644\u0645 \u0627\u0648\u0631 \u0641\u06c1\u0645 \u062d\u0627\u0635\u0644 \u06a9\u0631\u0646\u06d2 \u0645\u06cc\u06ba \u0634\u0627\u0645\u0644 \u0630\u06c1\u0646\u06cc \u0639\u0645\u0644 - \u062c\u06cc\u0633\u06d2 \u062a\u0648\u062c\u06c1\u060c \u06cc\u0627\u062f\u062f\u0627\u0634\u062a \u0627\u0648\u0631 \u0627\u0633\u062a\u062f\u0644\u0627\u0644\u06d4"},{"term":"Profession","definition_en":"An occupation that requires specialized training, follows a code of conduct, and is accountable to a professional community - such as teaching, medicine, or law.","definition_ur":"\u067e\u06cc\u0634\u06c1 \u0627\u06cc\u06a9 \u0627\u06cc\u0633\u0627 \u06a9\u0627\u0645 \u06c1\u06d2 \u062c\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u062e\u0635\u0648\u0635\u06cc \u062a\u0631\u0628\u06cc\u062a \u062f\u0631\u06a9\u0627\u0631 \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u060c \u062c\u0648 \u0627\u06cc\u06a9 \u0636\u0627\u0628\u0637\u06c1 \u0627\u062e\u0644\u0627\u0642 \u06a9\u06cc \u067e\u06cc\u0631\u0648\u06cc \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u060c \u0627\u0648\u0631 \u062c\u0648 \u0627\u067e\u0646\u06cc \u067e\u06cc\u0634\u06c1 \u0648\u0631\u0627\u0646\u06c1 \u0628\u0631\u0627\u062f\u0631\u06cc \u06a9\u06d2 \u0633\u0627\u0645\u0646\u06d2 \u062c\u0648\u0627\u0628\u062f\u06c1 \u06c1\u0648\u062a\u0627 \u06c1\u06d2 - \u062c\u06cc\u0633\u06d2 \u062a\u062f\u0631\u06cc\u0633\u060c \u0637\u0628\u060c \u06cc\u0627 \u0648\u06a9\u0627\u0644\u062a\u06d4"},{"term":"Professionalism","definition_en":"The quality of conducting oneself according to the standards, ethics, and responsibilities expected of a profession.","definition_ur":"\u067e\u06cc\u0634\u06c1 \u0648\u0627\u0631\u06cc\u062a \u0633\u06d2 \u0645\u0631\u0627\u062f \u06a9\u0633\u06cc \u067e\u06cc\u0634\u06d2 \u06a9\u06d2 \u0645\u062a\u0648\u0642\u0639 \u0645\u0639\u06cc\u0627\u0631\u0627\u062a\u060c \u0627\u062e\u0644\u0627\u0642\u06cc\u0627\u062a \u0627\u0648\u0631 \u0630\u0645\u06c1 \u062f\u0627\u0631\u06cc\u0648\u06ba \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u0627\u067e\u0646\u06d2 \u0622\u067e \u06a9\u0648 \u0686\u0644\u0627\u0646\u06d2 \u06a9\u06cc \u062e\u0648\u0628\u06cc \u06c1\u06d2\u06d4"},{"term":"Professional Ethics","definition_en":"The set of moral principles and standards of conduct that guide how members of a profession should behave toward those they serve and each other.","definition_ur":"\u0627\u062e\u0644\u0627\u0642\u06cc \u0627\u0635\u0648\u0644\u0648\u06ba \u0627\u0648\u0631 \u0636\u0627\u0628\u0637\u06c1 \u0627\u062e\u0644\u0627\u0642 \u06a9\u0627 \u0648\u06c1 \u0645\u062c\u0645\u0648\u0639\u06c1 \u062c\u0648 \u06a9\u0633\u06cc \u067e\u06cc\u0634\u06d2 \u06a9\u06d2 \u0627\u0631\u06a9\u0627\u0646 \u06a9\u06d2 \u0637\u0631\u0632\u0650 \u0639\u0645\u0644 \u06a9\u06cc \u0631\u06c1\u0646\u0645\u0627\u0626\u06cc \u06a9\u0631\u062a\u0627 \u06c1\u06d2 - \u0627\u064f\u0646 \u0644\u0648\u06af\u0648\u06ba \u06a9\u06d2 \u0633\u0627\u062a\u06be \u062c\u0646 \u06a9\u06cc \u0648\u06c1 \u062e\u062f\u0645\u062a \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06d2 \u0633\u0627\u062a\u06be\u06d4"},{"term":"Ethical Dilemma","definition_en":"A situation with no clearly right answer, where a professional must choose between competing values or responsibilities.","definition_ur":"\u0627\u06cc\u0633\u06cc \u0635\u0648\u0631\u062a\u062d\u0627\u0644 \u062c\u0633 \u06a9\u0627 \u06a9\u0648\u0626\u06cc \u0648\u0627\u0636\u062d \u0637\u0648\u0631 \u067e\u0631 \u062f\u0631\u0633\u062a \u062c\u0648\u0627\u0628 \u0646\u06c1 \u06c1\u0648\u060c \u062c\u06c1\u0627\u06ba \u0627\u06cc\u06a9 \u067e\u06cc\u0634\u06c1 \u0648\u0631 \u06a9\u0648 \u0628\u0627\u06c1\u0645 \u0645\u062a\u0635\u0627\u062f\u0645 \u0627\u0642\u062f\u0627\u0631 \u06cc\u0627 \u0630\u0645\u06c1 \u062f\u0627\u0631\u06cc\u0648\u06ba \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0631\u0646\u0627 \u067e\u0691\u06d2\u06d4"},{"term":"Continuous Professional Development","definition_en":"Ongoing learning and growth a teacher pursues throughout their career, through both formal activities (courses, conferences) and reflective practice (journals, peer feedback).","definition_ur":"\u0648\u06c1 \u0645\u0633\u0644\u0633\u0644 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u0627\u0648\u0631 \u062a\u0631\u0642\u06cc \u06a9\u0627 \u0639\u0645\u0644 \u062c\u0648 \u0627\u06cc\u06a9 \u0627\u0633\u062a\u0627\u062f \u0627\u067e\u0646\u06d2 \u067e\u0648\u0631\u06d2 \u06a9\u06cc\u0631\u06cc\u0626\u0631 \u06a9\u06d2 \u062f\u0648\u0631\u0627\u0646 \u062c\u0627\u0631\u06cc \u0631\u06a9\u06be\u062a\u0627 \u06c1\u06d2 - \u0631\u0633\u0645\u06cc \u0633\u0631\u06af\u0631\u0645\u06cc\u0648\u06ba (\u06a9\u0648\u0631\u0633\u0632\u060c \u06a9\u0627\u0646\u0641\u0631\u0646\u0633\u06cc\u06ba) \u0627\u0648\u0631 \u063a\u0648\u0631 \u0648 \u0641\u06a9\u0631 \u067e\u0631 \u0645\u0628\u0646\u06cc \u0639\u0645\u0644 (\u0688\u0627\u0626\u0631\u06cc \u0646\u0648\u06cc\u0633\u06cc\u060c \u06c1\u0645 \u0639\u0645\u0631 \u062a\u0627\u062b\u0631\u0627\u062a) \u062f\u0648\u0646\u0648\u06ba \u06a9\u06d2 \u0630\u0631\u06cc\u0639\u06d2\u06d4"},{"term":"Code of Ethical Conduct","definition_en":"A written statement of what a profession\'s members owe and to whom, usually organised by the party the obligation is owed to: students, one\'s own practice, parents and community, and colleagues.","definition_ur":"\u0627\u06cc\u06a9 \u062a\u062d\u0631\u06cc\u0631\u06cc \u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u062c\u0648 \u0628\u062a\u0627\u062a\u06cc \u06c1\u06d2 \u06a9\u06c1 \u067e\u06cc\u0634\u06d2 \u06a9\u06d2 \u0627\u0641\u0631\u0627\u062f \u067e\u0631 \u06a9\u06cc\u0627 \u0630\u0645\u06c1 \u062f\u0627\u0631\u06cc\u0627\u06ba \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u06a9\u0646 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06c1\u06cc\u06ba\u060c \u0639\u0645\u0648\u0645\u0627\u064b \u0627\u0633 \u0641\u0631\u06cc\u0642 \u06a9\u06d2 \u0627\u0639\u062a\u0628\u0627\u0631 \u0633\u06d2 \u062a\u0631\u062a\u06cc\u0628 \u062f\u06cc \u062c\u0627\u062a\u06cc \u06c1\u06d2 \u062c\u0633 \u06a9\u0627 \u062d\u0642 \u06c1\u06d2: \u0634\u0627\u06af\u0631\u062f\u060c \u0627\u067e\u0646\u0627 \u0639\u0645\u0644\u060c \u0648\u0627\u0644\u062f\u06cc\u0646 \u0627\u0648\u0631 \u0645\u0639\u0627\u0634\u0631\u06c1\u060c \u0627\u0648\u0631 \u06c1\u0645 \u067e\u06cc\u0634\u06c1 \u0627\u0641\u0631\u0627\u062f\u06d4"},{"term":"Reflective Decision Making","definition_en":"The habit of treating your own professional decisions as things to be examined rather than defended: structured, actively seeking evidence that the decision was wrong, and applied to routine cases rather than only dramatic ones.","definition_ur":"\u0627\u067e\u0646\u06d2 \u067e\u06cc\u0634\u06c1 \u0648\u0631\u0627\u0646\u06c1 \u0641\u06cc\u0635\u0644\u0648\u06ba \u06a9\u0648 \u062f\u0641\u0627\u0639 \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06d2 \u062c\u0627\u0646\u0686 \u06a9\u06d2 \u0644\u0627\u0626\u0642 \u0633\u0645\u062c\u06be\u0646\u06d2 \u06a9\u06cc \u0639\u0627\u062f\u062a: \u0645\u0646\u0638\u0645 \u0627\u0646\u062f\u0627\u0632 \u0645\u06cc\u06ba\u060c \u0627\u0633 \u0634\u06c1\u0627\u062f\u062a \u06a9\u06cc \u062a\u0644\u0627\u0634 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u06c1 \u0641\u06cc\u0635\u0644\u06c1 \u063a\u0644\u0637 \u062a\u06be\u0627\u060c \u0627\u0648\u0631 \u0635\u0631\u0641 \u063a\u06cc\u0631 \u0645\u0639\u0645\u0648\u0644\u06cc \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06d2 \u0631\u0648\u0632\u0645\u0631\u06c1 \u0645\u0639\u0627\u0645\u0644\u0627\u062a \u067e\u0631 \u0628\u06be\u06cc \u0644\u0627\u06af\u0648\u06d4"},{"term":"Teacher Effectiveness","definition_en":"The effect a teacher has on what their pupils learn. Definitions in use differ over which effects count: measured attainment gain, observed classroom practice, or the wider range of learner outcomes.","definition_ur":"\u0648\u06c1 \u0627\u062b\u0631 \u062c\u0648 \u0627\u0633\u062a\u0627\u062f \u0627\u067e\u0646\u06d2 \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u06d2 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u067e\u0631 \u0688\u0627\u0644\u062a\u0627 \u06c1\u06d2\u06d4 \u0631\u0627\u0626\u062c \u062a\u0639\u0631\u06cc\u0641\u06cc\u06ba \u0627\u0633 \u0628\u0627\u062a \u067e\u0631 \u0645\u062e\u062a\u0644\u0641 \u06c1\u06cc\u06ba \u06a9\u06c1 \u06a9\u0648\u0646 \u0633\u06d2 \u0627\u062b\u0631\u0627\u062a \u0634\u0645\u0627\u0631 \u06c1\u0648\u06ba: \u0646\u0627\u067e\u06cc \u06af\u0626\u06cc \u06a9\u0627\u0631\u06a9\u0631\u062f\u06af\u06cc \u0645\u06cc\u06ba \u0627\u0636\u0627\u0641\u06c1\u060c \u0645\u0634\u0627\u06c1\u062f\u06c1 \u0634\u062f\u06c1 \u062c\u0645\u0627\u0639\u062a\u06cc \u0639\u0645\u0644\u060c \u06cc\u0627 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u0648\u0627\u0644\u0648\u06ba \u06a9\u06d2 \u0648\u0633\u06cc\u0639 \u062a\u0631 \u0646\u062a\u0627\u0626\u062c\u06d4"},{"term":"Verbal Communication","definition_en":"The words themselves: what a teacher says, how it is structured, and whether the person hearing it can follow it. In a classroom it explains, instructs, questions and responds.","definition_ur":"\u0627\u0644\u0641\u0627\u0638 \u0628\u0630\u0627\u062a\u0650 \u062e\u0648\u062f: \u0627\u0633\u062a\u0627\u062f \u06a9\u06cc\u0627 \u06a9\u06c1\u062a\u0627 \u06c1\u06d2\u060c \u06a9\u0633 \u062a\u0631\u062a\u06cc\u0628 \u0633\u06d2 \u06a9\u06c1\u062a\u0627 \u06c1\u06d2\u060c \u0627\u0648\u0631 \u06a9\u06cc\u0627 \u0633\u0646\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0627\u0633\u06d2 \u0633\u0645\u062c\u06be \u0633\u06a9\u062a\u0627 \u06c1\u06d2\u06d4 \u062c\u0645\u0627\u0639\u062a \u0645\u06cc\u06ba \u06cc\u06c1 \u0648\u0636\u0627\u062d\u062a \u06a9\u0631\u062a\u0627\u060c \u06c1\u062f\u0627\u06cc\u062a \u062f\u06cc\u062a\u0627\u060c \u0633\u0648\u0627\u0644 \u06a9\u0631\u062a\u0627 \u0627\u0648\u0631 \u062c\u0648\u0627\u0628 \u062f\u06cc\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Non-verbal Communication","definition_en":"Everything carried outside the words: proximity, body orientation, gaze and eye contact, facial expression, gesture and vocal variety. Learners read these fast and follow them when they contradict the words.","definition_ur":"\u0648\u06c1 \u0633\u0628 \u06a9\u0686\u06be \u062c\u0648 \u0627\u0644\u0641\u0627\u0638 \u0633\u06d2 \u0628\u0627\u06c1\u0631 \u0645\u0646\u062a\u0642\u0644 \u06c1\u0648\u062a\u0627 \u06c1\u06d2: \u0642\u0631\u0628\u062a\u060c \u062c\u0633\u0645 \u06a9\u0627 \u0631\u062e\u060c \u0646\u06af\u0627\u06c1 \u0627\u0648\u0631 \u0622\u0646\u06a9\u06be \u06a9\u0627 \u0645\u0644\u0627\u067e\u060c \u0686\u06c1\u0631\u06d2 \u06a9\u06d2 \u062a\u0627\u062b\u0631\u0627\u062a\u060c \u0627\u0634\u0627\u0631\u06d2 \u0627\u0648\u0631 \u0622\u0648\u0627\u0632 \u06a9\u0627 \u0627\u062a\u0627\u0631 \u0686\u0691\u06be\u0627\u0624\u06d4 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0627\u0646\u06c1\u06cc\u06ba \u062a\u06cc\u0632\u06cc \u0633\u06d2 \u067e\u0691\u06be\u062a\u06d2 \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u0627\u0644\u0641\u0627\u0638 \u0633\u06d2 \u062a\u0636\u0627\u062f \u06a9\u06cc \u0635\u0648\u0631\u062a \u0645\u06cc\u06ba \u0627\u0646\u06c1\u06cc \u06a9\u06cc \u067e\u06cc\u0631\u0648\u06cc \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Professional Standards","definition_en":"A documented statement of the knowledge, values and practice expected of a competent member of a profession, written specifically enough that someone can judge whether it has been met.","definition_ur":"\u0627\u06cc\u06a9 \u062a\u062d\u0631\u06cc\u0631\u06cc \u0628\u06cc\u0627\u0646 \u062c\u0648 \u0627\u0633 \u0639\u0644\u0645\u060c \u0627\u0642\u062f\u0627\u0631 \u0627\u0648\u0631 \u0639\u0645\u0644 \u06a9\u0648 \u0628\u06cc\u0627\u0646 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u062c\u0648 \u067e\u06cc\u0634\u06d2 \u06a9\u06d2 \u0627\u06cc\u06a9 \u0627\u06c1\u0644 \u0641\u0631\u062f \u0633\u06d2 \u0645\u062a\u0648\u0642\u0639 \u06c1\u06d2\u060c \u0627\u0648\u0631 \u0627\u062a\u0646\u0627 \u0645\u062e\u0635\u0648\u0635 \u06c1\u0648\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u06a9\u0648\u0626\u06cc \u067e\u0631\u06a9\u06be \u0633\u06a9\u06d2 \u06a9\u06c1 \u0648\u06c1 \u067e\u0648\u0631\u0627 \u06c1\u0648\u0627 \u06cc\u0627 \u0646\u06c1\u06cc\u06ba\u06d4"},{"term":"National Professional Standards for Teachers","definition_en":"Pakistan\'s framework of ten teaching standards, issued by the Ministry of Education in 2009 with UNESCO and USAID support. Each standard is divided into knowledge and understanding, dispositions, and performance and skills, with indicators beneath.","definition_ur":"\u067e\u0627\u06a9\u0633\u062a\u0627\u0646 \u06a9\u06d2 \u062f\u0633 \u062a\u062f\u0631\u06cc\u0633\u06cc \u0645\u0639\u06cc\u0627\u0631\u0627\u062a \u06a9\u0627 \u0688\u06be\u0627\u0646\u0686\u06c1\u060c \u062c\u0648 \u0648\u0632\u0627\u0631\u062a\u0650 \u062a\u0639\u0644\u06cc\u0645 \u0646\u06d2 2009 \u0645\u06cc\u06ba \u06cc\u0648\u0646\u06cc\u0633\u06a9\u0648 \u0627\u0648\u0631 \u06cc\u0648 \u0627\u06cc\u0633 \u0627\u06cc\u0688 \u06a9\u06d2 \u062a\u0639\u0627\u0648\u0646 \u0633\u06d2 \u062c\u0627\u0631\u06cc \u06a9\u06cc\u0627\u06d4 \u06c1\u0631 \u0645\u0639\u06cc\u0627\u0631 \u0639\u0644\u0645 \u0648 \u0641\u06c1\u0645\u060c \u0631\u062c\u062d\u0627\u0646\u0627\u062a\u060c \u0627\u0648\u0631 \u06a9\u0627\u0631\u06a9\u0631\u062f\u06af\u06cc \u0648 \u0645\u06c1\u0627\u0631\u062a \u0645\u06cc\u06ba \u062a\u0642\u0633\u06cc\u0645 \u06c1\u06d2\u060c \u062c\u0646 \u06a9\u06d2 \u0646\u06cc\u0686\u06d2 \u0627\u0634\u0627\u0631\u06cc\u06d2 \u06c1\u0648\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Teacher Licensing","definition_en":"Permission to practise as a teacher, issued by an authority, usually time-limited and renewable. It differs from certification, which confirms that a person completed the required preparation.","definition_ur":"\u06a9\u0633\u06cc \u0645\u062c\u0627\u0632 \u0627\u062f\u0627\u0631\u06d2 \u06a9\u06cc \u062c\u0627\u0646\u0628 \u0633\u06d2 \u062a\u062f\u0631\u06cc\u0633 \u06a9\u06cc \u0627\u062c\u0627\u0632\u062a\u060c \u062c\u0648 \u0639\u0645\u0648\u0645\u0627\u064b \u0645\u0642\u0631\u0631\u06c1 \u0645\u062f\u062a \u06a9\u06d2 \u0644\u06cc\u06d2 \u06c1\u0648\u062a\u06cc \u06c1\u06d2 \u0627\u0648\u0631 \u0642\u0627\u0628\u0644\u0650 \u062a\u062c\u062f\u06cc\u062f \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4 \u06cc\u06c1 \u0633\u0646\u062f \u0628\u0646\u062f\u06cc \u0633\u06d2 \u0645\u062e\u062a\u0644\u0641 \u06c1\u06d2\u060c \u062c\u0648 \u0635\u0631\u0641 \u0645\u0637\u0644\u0648\u0628\u06c1 \u062a\u06cc\u0627\u0631\u06cc \u0645\u06a9\u0645\u0644 \u06c1\u0648\u0646\u06d2 \u06a9\u06cc \u062a\u0635\u062f\u06cc\u0642 \u06a9\u0631\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Burnout","definition_en":"What chronic, unresolved demand produces over time, with three dimensions: exhaustion, cynicism or distancing from the work, and a reduced sense of accomplishment. It differs from stress, which is episodic and resolves when the demand passes.","definition_ur":"\u0648\u06c1 \u06a9\u06cc\u0641\u06cc\u062a \u062c\u0648 \u0645\u0633\u0644\u0633\u0644 \u0627\u0648\u0631 \u063a\u06cc\u0631 \u062d\u0644 \u0634\u062f\u06c1 \u062a\u0642\u0627\u0636\u0648\u06ba \u0633\u06d2 \u0648\u0642\u062a \u06a9\u06d2 \u0633\u0627\u062a\u06be \u067e\u06cc\u062f\u0627 \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u060c \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06d2 \u062a\u06cc\u0646 \u067e\u06c1\u0644\u0648 \u06c1\u06cc\u06ba: \u062a\u06be\u06a9\u0646\u060c \u06a9\u0627\u0645 \u0633\u06d2 \u0628\u06cc\u0632\u0627\u0631\u06cc \u06cc\u0627 \u062f\u0648\u0631\u06cc\u060c \u0627\u0648\u0631 \u06cc\u06c1 \u0627\u062d\u0633\u0627\u0633 \u06a9\u06c1 \u06a9\u0686\u06be \u0641\u0631\u0642 \u0646\u06c1\u06cc\u06ba \u067e\u0691\u062a\u0627\u06d4 \u06cc\u06c1 \u062f\u0628\u0627\u0624 \u0633\u06d2 \u0645\u062e\u062a\u0644\u0641 \u06c1\u06d2\u060c \u062c\u0648 \u0648\u0642\u062a\u06cc \u06c1\u0648\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u062a\u0642\u0627\u0636\u0627 \u062e\u062a\u0645 \u06c1\u0648\u0646\u06d2 \u067e\u0631 \u062e\u062a\u0645 \u06c1\u0648 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Multi-grade Classroom","definition_en":"A classroom in which one teacher is responsible for pupils of two or more grade levels at the same time, in the same room. Common wherever enrolment is small or teachers few, and requiring skills most teacher preparation does not teach.","definition_ur":"\u0627\u06cc\u0633\u0627 \u06a9\u0644\u0627\u0633 \u0631\u0648\u0645 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u06c1\u06cc \u0627\u0633\u062a\u0627\u062f \u0627\u06cc\u06a9 \u06c1\u06cc \u0648\u0642\u062a \u0627\u0648\u0631 \u0627\u06cc\u06a9 \u06c1\u06cc \u06a9\u0645\u0631\u06d2 \u0645\u06cc\u06ba \u062f\u0648 \u06cc\u0627 \u0632\u06cc\u0627\u062f\u06c1 \u062f\u0631\u062c\u0627\u062a \u06a9\u06d2 \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u0627 \u0630\u0645\u06c1 \u062f\u0627\u0631 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4 \u06cc\u06c1 \u0648\u06c1\u0627\u06ba \u0639\u0627\u0645 \u06c1\u06d2 \u062c\u06c1\u0627\u06ba \u062f\u0627\u062e\u0644\u06d2 \u06a9\u0645 \u06c1\u0648\u06ba \u06cc\u0627 \u0627\u0633\u0627\u062a\u0630\u06c1 \u06a9\u0645\u060c \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0648\u06c1 \u0645\u06c1\u0627\u0631\u062a\u06cc\u06ba \u062f\u0631\u06a9\u0627\u0631 \u06c1\u06cc\u06ba \u062c\u0648 \u0632\u06cc\u0627\u062f\u06c1 \u062a\u0631 \u062a\u0631\u0628\u06cc\u062a \u0645\u06cc\u06ba \u0646\u06c1\u06cc\u06ba \u0633\u06a9\u06be\u0627\u0626\u06cc \u062c\u0627\u062a\u06cc\u06ba\u06d4"},{"term":"Occupational Status","definition_en":"The standing a society accords a line of work: what it pays, who it attracts, how it is spoken about, and how much independence its members are granted. It is distinct from the recognition individual practitioners earn in their own community.","definition_ur":"\u0648\u06c1 \u0645\u0642\u0627\u0645 \u062c\u0648 \u0645\u0639\u0627\u0634\u0631\u06c1 \u06a9\u0633\u06cc \u067e\u06cc\u0634\u06d2 \u06a9\u0648 \u062f\u06cc\u062a\u0627 \u06c1\u06d2: \u0627\u0633 \u06a9\u06cc \u062a\u0646\u062e\u0648\u0627\u06c1\u060c \u0627\u0633 \u06a9\u06cc \u062c\u0627\u0646\u0628 \u0631\u0627\u063a\u0628 \u06c1\u0648\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0627\u0641\u0631\u0627\u062f\u060c \u0627\u0633 \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u06af\u0641\u062a\u06af\u0648\u060c \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06d2 \u0627\u0631\u06a9\u0627\u0646 \u06a9\u0648 \u062f\u06cc \u062c\u0627\u0646\u06d2 \u0648\u0627\u0644\u06cc \u062e\u0648\u062f\u0645\u062e\u062a\u0627\u0631\u06cc\u06d4 \u06cc\u06c1 \u0627\u0633 \u067e\u0630\u06cc\u0631\u0627\u0626\u06cc \u0633\u06d2 \u0627\u0644\u06af \u06c1\u06d2 \u062c\u0648 \u0627\u0646\u0641\u0631\u0627\u062f\u06cc \u0627\u06c1\u0644\u06a9\u0627\u0631 \u0627\u067e\u0646\u06cc \u0628\u0631\u0627\u062f\u0631\u06cc \u0645\u06cc\u06ba \u06a9\u0645\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Professional Learning Community","definition_en":"A group of teachers in the same school who meet regularly to examine their own practice and their pupils\' learning, with a shared focus and an expectation that what is discussed is acted on.","definition_ur":"\u0627\u06cc\u06a9 \u06c1\u06cc \u0627\u0633\u06a9\u0648\u0644 \u06a9\u06d2 \u0627\u0633\u0627\u062a\u0630\u06c1 \u06a9\u0627 \u06af\u0631\u0648\u06c1 \u062c\u0648 \u0628\u0627\u0642\u0627\u0639\u062f\u06af\u06cc \u0633\u06d2 \u0645\u0644 \u06a9\u0631 \u0627\u067e\u0646\u06d2 \u0639\u0645\u0644 \u0627\u0648\u0631 \u0627\u067e\u0646\u06d2 \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u06d2 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u06a9\u0627 \u062c\u0627\u0626\u0632\u06c1 \u0644\u06cc\u062a\u0627 \u06c1\u06d2\u060c \u0627\u06cc\u06a9 \u0645\u0634\u062a\u0631\u06a9\u06c1 \u062a\u0648\u062c\u06c1 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0627\u0648\u0631 \u0627\u0633 \u062a\u0648\u0642\u0639 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u06c1 \u062c\u0648 \u0632\u06cc\u0631\u0650 \u0628\u062d\u062b \u0622\u0626\u06d2 \u0627\u0633 \u067e\u0631 \u0639\u0645\u0644 \u0628\u06be\u06cc \u06c1\u0648\u06d4"},{"term":"Reflective Practice","definition_en":"The disciplined examination of your own teaching against evidence, including your pupils\' experience of it and a colleague\'s view of it. It is a professional method rather than a disposition, and it is not the same as keeping a diary of feelings.","definition_ur":"\u0634\u06c1\u0627\u062f\u062a \u06a9\u06cc \u0631\u0648\u0634\u0646\u06cc \u0645\u06cc\u06ba \u0627\u067e\u0646\u06cc \u062a\u062f\u0631\u06cc\u0633 \u06a9\u0627 \u0645\u0646\u0638\u0645 \u062c\u0627\u0626\u0632\u06c1\u060c \u062c\u0633 \u0645\u06cc\u06ba \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u0627 \u062a\u062c\u0631\u0628\u06c1 \u0627\u0648\u0631 \u06a9\u0633\u06cc \u06c1\u0645 \u067e\u06cc\u0634\u06c1 \u06a9\u06cc \u0631\u0627\u0626\u06d2 \u0628\u06be\u06cc \u0634\u0627\u0645\u0644 \u06c1\u0648\u06d4 \u06cc\u06c1 \u0627\u06cc\u06a9 \u067e\u06cc\u0634\u06c1 \u0648\u0631\u0627\u0646\u06c1 \u0637\u0631\u06cc\u0642\u06c1 \u06a9\u0627\u0631 \u06c1\u06d2\u060c \u0645\u062d\u0636 \u0627\u06cc\u06a9 \u0631\u062c\u062d\u0627\u0646 \u0646\u06c1\u06cc\u06ba\u060c \u0627\u0648\u0631 \u06cc\u06c1 \u062c\u0630\u0628\u0627\u062a \u06a9\u06cc \u0688\u0627\u0626\u0631\u06cc \u0631\u06a9\u06be\u0646\u06d2 \u0633\u06d2 \u0645\u062e\u062a\u0644\u0641 \u06c1\u06d2\u06d4"},{"term":"Professional Development Plan","definition_en":"A short written statement, ideally one page, of what a teacher intends to get better at, how, and how they will know: the gap, the evidence for it, one goal, the activity, the evidence of change, and a review date.","definition_ur":"\u0627\u06cc\u06a9 \u0645\u062e\u062a\u0635\u0631 \u062a\u062d\u0631\u06cc\u0631\u06cc \u0628\u06cc\u0627\u0646\u060c \u0628\u06c1\u062a\u0631 \u06c1\u06d2 \u06a9\u06c1 \u0627\u06cc\u06a9 \u0635\u0641\u062d\u06d2 \u06a9\u0627\u060c \u06a9\u06c1 \u0627\u0633\u062a\u0627\u062f \u06a9\u0633 \u0686\u06cc\u0632 \u0645\u06cc\u06ba \u0628\u06c1\u062a\u0631\u06cc \u0686\u0627\u06c1\u062a\u0627 \u06c1\u06d2\u060c \u06a9\u06cc\u0633\u06d2\u060c \u0627\u0648\u0631 \u06a9\u06cc\u0633\u06d2 \u062c\u0627\u0646\u06d2 \u06af\u0627: \u06a9\u0645\u06cc\u060c \u0627\u0633 \u06a9\u06cc \u0634\u06c1\u0627\u062f\u062a\u060c \u0627\u06cc\u06a9 \u06c1\u062f\u0641\u060c \u0633\u0631\u06af\u0631\u0645\u06cc\u060c \u062a\u0628\u062f\u06cc\u0644\u06cc \u06a9\u06cc \u0634\u06c1\u0627\u062f\u062a\u060c \u0627\u0648\u0631 \u062c\u0627\u0626\u0632\u06d2 \u06a9\u06cc \u062a\u0627\u0631\u06cc\u062e\u06d4"},{"term":"Behaviourism","definition_en":"The theory that learning is a change in observable behaviour shaped by the interaction between a stimulus and a response, and by the reinforcement that follows.","definition_ur":"\u0648\u06c1 \u0646\u0638\u0631\u06cc\u06c1 \u062c\u0633 \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u0633\u06cc\u06a9\u06be\u0646\u0627 \u0645\u0634\u0627\u06c1\u062f\u06c1 \u06c1\u0648\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0631\u0648\u06cc\u06d2 \u0645\u06cc\u06ba \u062a\u0628\u062f\u06cc\u0644\u06cc \u06c1\u06d2 \u062c\u0648 \u0645\u062d\u0631\u06a9 \u0627\u0648\u0631 \u0631\u062f\u0639\u0645\u0644 \u06a9\u06d2 \u0628\u0627\u06c1\u0645 \u062a\u0639\u0627\u0645\u0644 \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06d2 \u0628\u0639\u062f \u0622\u0646\u06d2 \u0648\u0627\u0644\u06cc \u062a\u0642\u0648\u06cc\u062a \u0633\u06d2 \u0634\u06a9\u0644 \u0644\u06cc\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Cognitivism","definition_en":"The theory that learning is the reorganisation of mental structures: the mind processes new information against what it already knows and reshapes its internal understanding.","definition_ur":"\u0648\u06c1 \u0646\u0638\u0631\u06cc\u06c1 \u062c\u0633 \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u0633\u06cc\u06a9\u06be\u0646\u0627 \u0630\u06c1\u0646\u06cc \u0688\u06be\u0627\u0646\u0686\u0648\u06ba \u06a9\u06cc \u0646\u0626\u06cc \u062a\u0631\u062a\u06cc\u0628 \u06c1\u06d2: \u0630\u06c1\u0646 \u0646\u0626\u06cc \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u06a9\u0627 \u0645\u0639\u0627\u0645\u0644\u06c1 \u0627\u0633 \u06a9\u06d2 \u067e\u06c1\u0644\u06d2 \u0633\u06d2 \u0645\u0648\u062c\u0648\u062f \u0639\u0644\u0645 \u06a9\u06d2 \u062e\u0644\u0627\u0641 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0627\u067e\u0646\u06cc \u0627\u0646\u062f\u0631\u0648\u0646\u06cc \u0633\u0645\u062c\u06be \u06a9\u0648 \u0646\u0626\u06cc \u0634\u06a9\u0644 \u062f\u06cc\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Constructivism","definition_en":"The theory that learning is the active construction of personal meaning by the learner, rather than the transfer of intact knowledge from teacher to pupil.","definition_ur":"\u0648\u06c1 \u0646\u0638\u0631\u06cc\u06c1 \u062c\u0633 \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u0633\u06cc\u06a9\u06be\u0646\u0627 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u06a9\u06cc \u0637\u0631\u0641 \u0633\u06d2 \u0630\u0627\u062a\u06cc \u0645\u0639\u0646\u06cc \u06a9\u06cc \u0641\u0639\u0627\u0644 \u062a\u0639\u0645\u06cc\u0631 \u06c1\u06d2\u060c \u0646\u06c1 \u06a9\u06c1 \u0627\u0633\u062a\u0627\u062f \u0633\u06d2 \u0634\u0627\u06af\u0631\u062f \u062a\u06a9 \u0645\u06a9\u0645\u0644 \u0639\u0644\u0645 \u0645\u0646\u062a\u0642\u0644 \u06c1\u0648\u0646\u0627\u06d4"},{"term":"Classroom management","definition_en":"The set of proactive teacher actions whose purpose is to create and maintain the conditions in which student learning can happen.","definition_ur":"\u0627\u0633\u062a\u0627\u062f \u06a9\u06cc \u0627\u06cc\u0633\u06cc \u0641\u0639\u0627\u0644 \u06a9\u0627\u0631\u0631\u0648\u0627\u0626\u06cc\u0648\u06ba \u06a9\u0627 \u0645\u062c\u0645\u0648\u0639\u06c1 \u062c\u0633 \u06a9\u0627 \u0645\u0642\u0635\u062f \u0627\u06cc\u0633\u06cc \u0635\u0648\u0631\u062a\u062d\u0627\u0644 \u067e\u06cc\u062f\u0627 \u06a9\u0631\u0646\u0627 \u0627\u0648\u0631 \u0628\u0631\u0642\u0631\u0627\u0631 \u0631\u06a9\u06be\u0646\u0627 \u06c1\u06d2 \u062c\u0633 \u0645\u06cc\u06ba \u0634\u0627\u06af\u0631\u062f \u0633\u06cc\u06a9\u06be \u0633\u06a9\u06cc\u06ba\u06d4"},{"term":"Discipline","definition_en":"The reactive teacher response after a pupil has breached a classroom norm: the reminder, the consequence, or the conversation that restores the norm.","definition_ur":"\u0634\u0627\u06af\u0631\u062f \u06a9\u06d2 \u06a9\u0644\u0627\u0633 \u06a9\u06d2 \u0627\u0635\u0648\u0644 \u062a\u0648\u0691\u0646\u06d2 \u06a9\u06d2 \u0628\u0639\u062f \u0627\u0633\u062a\u0627\u062f \u06a9\u06cc \u0631\u062f\u0639\u0645\u0644\u06cc \u06a9\u0627\u0631\u0631\u0648\u0627\u0626\u06cc: \u06cc\u0627\u062f \u062f\u06c1\u0627\u0646\u06cc\u060c \u0646\u062a\u06cc\u062c\u06c1\u060c \u06cc\u0627 \u0648\u06c1 \u06af\u0641\u062a\u06af\u0648 \u062c\u0648 \u0627\u0635\u0648\u0644 \u0628\u062d\u0627\u0644 \u06a9\u0631\u06d2\u06d4"},{"term":"Physical environment","definition_en":"The material features of a classroom a teacher can arrange or influence: furniture, displays, resources, lighting, and the use of wall and floor space.","definition_ur":"\u06a9\u0644\u0627\u0633 \u06a9\u06cc \u0648\u06c1 \u0645\u0627\u062f\u06cc \u062e\u0635\u0648\u0635\u06cc\u0627\u062a \u062c\u0648 \u0627\u0633\u062a\u0627\u062f \u062a\u0631\u062a\u06cc\u0628 \u062f\u06d2 \u0633\u06a9\u062a\u0627 \u06c1\u06d2 \u06cc\u0627 \u067e\u0631 \u0627\u062b\u0631 \u06c1\u0648 \u0633\u06a9\u062a\u0627 \u06c1\u06d2: \u0641\u0631\u0646\u06cc\u0686\u0631\u060c \u0646\u0645\u0627\u0626\u0634\u06cc\u06ba\u060c \u0648\u0633\u0627\u0626\u0644\u060c \u0631\u0648\u0634\u0646\u06cc\u060c \u0627\u0648\u0631 \u062f\u06cc\u0648\u0627\u0631 \u0627\u0648\u0631 \u0641\u0631\u0634 \u06a9\u0627 \u0627\u0633\u062a\u0639\u0645\u0627\u0644\u06d4"},{"term":"Social environment","definition_en":"The relationships and norms that govern how people in a classroom treat each other: between teacher and pupils, among pupils, and between the class and any outsider.","definition_ur":"\u0648\u06c1 \u0631\u0634\u062a\u06d2 \u0627\u0648\u0631 \u0627\u0635\u0648\u0644 \u062c\u0648 \u06a9\u0644\u0627\u0633 \u0645\u06cc\u06ba \u0644\u0648\u06af\u0648\u06ba \u06a9\u06d2 \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0633\u0644\u0648\u06a9 \u06a9\u0627 \u062a\u0639\u06cc\u0646 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba: \u0627\u0633\u062a\u0627\u062f \u0627\u0648\u0631 \u0634\u0627\u06af\u0631\u062f \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646\u060c \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u06d2 \u0628\u0627\u06c1\u0645\u060c \u0627\u0648\u0631 \u062c\u0645\u0627\u0639\u062a \u0627\u0648\u0631 \u06a9\u0633\u06cc \u0628\u06cc\u0631\u0648\u0646\u06cc \u0634\u062e\u0635 \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646\u06d4"},{"term":"Classroom observation","definition_en":"The structured act of watching a classroom with a specific focus, recording what is seen in a consistent format, and keeping a clear line between what was observed and what is inferred.","definition_ur":"\u06a9\u0644\u0627\u0633 \u06a9\u06cc \u0628\u0627\u0642\u0627\u0639\u062f\u06c1 \u0646\u06af\u0631\u0627\u0646\u06cc \u062c\u0633 \u0645\u06cc\u06ba \u0645\u062e\u0635\u0648\u0635 \u062a\u0648\u062c\u06c1 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0645\u0634\u0627\u06c1\u062f\u06c1 \u06a9\u06cc\u0627 \u062c\u0627\u0626\u06d2\u060c \u062f\u06cc\u06a9\u06be\u06cc \u06af\u06cc\u06cc \u0686\u06cc\u0632\u0648\u06ba \u06a9\u0648 \u0628\u0627\u0627\u0635\u0648\u0644 \u0634\u06a9\u0644 \u0645\u06cc\u06ba \u0631\u06cc\u06a9\u0627\u0631\u0688 \u06a9\u06cc\u0627 \u062c\u0627\u0626\u06d2\u060c \u0627\u0648\u0631 \u0645\u0634\u0627\u06c1\u062f\u06d2 \u0627\u0648\u0631 \u0627\u0633 \u0633\u06d2 \u0646\u06a9\u0644\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0646\u062a\u06cc\u062c\u06d2 \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646 \u0648\u0627\u0636\u062d \u062d\u062f \u0628\u0631\u0642\u0631\u0627\u0631 \u0631\u06a9\u06be\u06cc \u062c\u0627\u0626\u06d2\u06d4"},{"term":"Well-managed classroom","definition_en":"A classroom marked by practised routines, high intellectual demand, teacher withitness, and a physical and social environment that supports the intended learning.","definition_ur":"\u0627\u06cc\u0633\u06cc \u06a9\u0644\u0627\u0633 \u062c\u0633 \u06a9\u06cc \u0646\u0634\u0627\u0646\u062f\u06c1\u06cc \u06a9\u0631\u0646\u06d2 \u0648\u0627\u0644\u06cc \u062e\u0635\u0648\u0635\u06cc\u0627\u062a \u06cc\u06c1 \u06c1\u06cc\u06ba: \u067e\u0631\u06a9\u06be\u06cc \u06af\u0626\u06cc \u0645\u0634\u0642\u06cc\u06ba\u060c \u0627\u062f\u0631\u06a9\u06cc \u0627\u0639\u0644\u06cc \u0633\u0637\u062d \u06a9\u0627 \u062a\u0642\u0627\u0636\u06c1\u060c \u0627\u0633\u062a\u0627\u062f \u06a9\u06cc \u0686\u0648\u06a9\u0633\u06cc\u060c \u0627\u0648\u0631 \u0627\u06cc\u0633\u0627 \u0645\u0627\u062f\u06cc \u0627\u0648\u0631 \u0645\u0639\u0627\u0634\u0631\u062a\u06cc \u0645\u0627\u062d\u0648\u0644 \u062c\u0633 \u0633\u06d2 \u0645\u0637\u0644\u0648\u0628\u06c1 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u06a9\u0648 \u0645\u062f\u062f \u0645\u0644\u06d2\u06d4"},{"term":"Learning resources","definition_en":"Anything in a classroom a pupil can use to support learning: textbooks, exercise books, the blackboard, posters, real objects, the floor, the wall, and other pupils.","definition_ur":"\u06a9\u0644\u0627\u0633 \u0645\u06cc\u06ba \u0645\u0648\u062c\u0648\u062f \u0648\u06c1 \u06a9\u0648\u0626\u06cc \u0628\u06be\u06cc \u0686\u06cc\u0632 \u062c\u0648 \u0634\u0627\u06af\u0631\u062f \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u0645\u06cc\u06ba \u0645\u062f\u062f \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631 \u0633\u06a9\u06d2: \u062f\u0631\u0633\u06cc \u06a9\u062a\u0627\u0628\u06cc\u06ba\u060c \u0645\u0634\u0642\u06cc\u06ba\u060c \u0628\u0648\u0631\u0688\u060c \u067e\u0648\u0633\u0679\u0631\u060c \u062d\u0642\u06cc\u0642\u06cc \u0627\u0634\u06cc\u0627\u0621\u060c \u0641\u0631\u0634\u060c \u062f\u06cc\u0648\u0627\u0631\u060c \u0627\u0648\u0631 \u062f\u0648\u0633\u0631\u06d2 \u0634\u0627\u06af\u0631\u062f\u06d4"},{"term":"Classroom challenges","definition_en":"The recurring frictions that make classroom management harder than textbook routines suggest, including multigrade or overcrowded rooms, resource scarcity, diverse pupil preparation, and unpredictable events.","definition_ur":"\u0648\u06c1 \u0628\u0627\u0631 \u0628\u0627\u0631 \u0622\u0646\u06d2 \u0648\u0627\u0644\u06cc \u0645\u0634\u06a9\u0644\u0627\u062a \u062c\u0648 \u06a9\u0644\u0627\u0633 \u06a9\u06d2 \u0627\u0646\u062a\u0638\u0627\u0645 \u06a9\u0648 \u06a9\u062a\u0627\u0628\u06cc \u06c1\u062f\u0627\u06cc\u0627\u062a \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u0645\u0634\u06a9\u0644 \u0628\u0646\u0627\u062a\u06cc \u06c1\u06cc\u06ba\u060c \u062c\u0646 \u0645\u06cc\u06ba \u0645\u0644\u0679\u06cc \u06af\u0631\u06cc\u0688 \u06cc\u0627 \u0628\u06be\u0631\u06d2 \u06c1\u0648\u0626\u06d2 \u06a9\u0645\u0631\u06d2\u060c \u0648\u0633\u0627\u0626\u0644 \u06a9\u06cc \u06a9\u0645\u06cc\u060c \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u06cc \u0645\u062a\u0646\u0648\u0639 \u062a\u06cc\u0627\u0631\u06cc\u060c \u0627\u0648\u0631 \u063a\u06cc\u0631 \u0645\u062a\u0648\u0642\u0639 \u0648\u0627\u0642\u0639\u0627\u062a \u0634\u0627\u0645\u0644 \u06c1\u06cc\u06ba\u06d4"},{"term":"Thinking","definition_en":"The set of mental functions - remembering, imagining, believing, deciding and reasoning - through which a person takes in information and works on it.","definition_ur":"\u0630\u06c1\u0646\u06cc \u0627\u0641\u0639\u0627\u0644 \u06a9\u0627 \u0645\u062c\u0645\u0648\u0639\u06c1 - \u06cc\u0627\u062f \u0631\u06a9\u06be\u0646\u0627\u060c \u062a\u0635\u0648\u0631 \u06a9\u0631\u0646\u0627\u060c \u06cc\u0642\u06cc\u0646 \u06a9\u0631\u0646\u0627\u060c \u0641\u06cc\u0635\u0644\u06c1 \u06a9\u0631\u0646\u0627 \u0627\u0648\u0631 \u0627\u0633\u062a\u062f\u0644\u0627\u0644 \u06a9\u0631\u0646\u0627 - \u062c\u0633 \u06a9\u06d2 \u0630\u0631\u06cc\u0639\u06d2 \u0627\u0646\u0633\u0627\u0646 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u062d\u0627\u0635\u0644 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0627\u0646 \u067e\u0631 \u06a9\u0627\u0645 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Egocentrism","definition_en":"The habit of seeing everything from your own position and assuming your view is the natural one - a common barrier to critical thinking.","definition_ur":"\u0627\u067e\u0646\u06cc \u062c\u06af\u06c1 \u0633\u06d2 \u06c1\u0631 \u0686\u06cc\u0632 \u062f\u06cc\u06a9\u06be\u0646\u06d2 \u0627\u0648\u0631 \u0627\u067e\u0646\u06cc \u0631\u0627\u0626\u06d2 \u06a9\u0648 \u0641\u0637\u0631\u06cc \u0633\u0645\u062c\u06be\u0646\u06d2 \u06a9\u06cc \u0639\u0627\u062f\u062a - \u062a\u0646\u0642\u06cc\u062f\u06cc \u0633\u0648\u0686 \u0645\u06cc\u06ba \u0631\u06a9\u0627\u0648\u0679 \u06a9\u0627 \u0627\u06cc\u06a9 \u0639\u0627\u0645 \u0633\u0628\u0628\u06d4"},{"term":"Group conformity","definition_en":"The pressure to think along with those around you, accepting the group\'s view without examining it - a common barrier to critical thinking.","definition_ur":"\u0627\u067e\u0646\u06d2 \u0627\u0631\u062f \u06af\u0631\u062f \u06a9\u06d2 \u0644\u0648\u06af\u0648\u06ba \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0633\u0648\u0686\u0646\u06d2 \u06a9\u0627 \u062f\u0628\u0627\u0624\u060c \u06af\u0631\u0648\u06c1 \u06a9\u06cc \u0631\u0627\u0626\u06d2 \u06a9\u0648 \u062c\u0627\u0646\u0686\u06d2 \u0628\u063a\u06cc\u0631 \u0642\u0628\u0648\u0644 \u06a9\u0631\u0646\u0627 - \u062a\u0646\u0642\u06cc\u062f\u06cc \u0633\u0648\u0686 \u0645\u06cc\u06ba \u0631\u06a9\u0627\u0648\u0679 \u06a9\u0627 \u0627\u06cc\u06a9 \u0639\u0627\u0645 \u0633\u0628\u0628\u06d4"},{"term":"Statement","definition_en":"A sentence that claims something is or is not the case - something that can, in principle, be true or false.","definition_ur":"\u0627\u06cc\u06a9 \u062c\u0645\u0644\u06c1 \u062c\u0648 \u062f\u0639\u0648\u06cc \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u06a9\u0648\u0626\u06cc \u0686\u06cc\u0632 \u06c1\u06d2 \u06cc\u0627 \u0646\u06c1\u06cc\u06ba \u06c1\u06d2 - \u0627\u06cc\u0633\u06cc \u0686\u06cc\u0632 \u062c\u0648 \u0627\u0635\u0648\u0644 \u0637\u0648\u0631 \u067e\u0631 \u062f\u0631\u0633\u062a \u06cc\u0627 \u063a\u0644\u0637 \u06c1\u0648 \u0633\u06a9\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Claim","definition_en":"A statement put forward as true, often in the face of possible disagreement - a statement that needs support.","definition_ur":"\u0627\u06cc\u06a9 \u0628\u06cc\u0627\u0646 \u062c\u0648 \u062f\u0631\u0633\u062a \u06a9\u06d2 \u0637\u0648\u0631 \u067e\u0631 \u067e\u06cc\u0634 \u06a9\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u060c \u0627\u06a9\u062b\u0631 \u0645\u0645\u06a9\u0646\u06c1 \u0627\u062e\u062a\u0644\u0627\u0641 \u06a9\u06d2 \u0628\u0627\u0648\u062c\u0648\u062f - \u0627\u06cc\u06a9 \u0628\u06cc\u0627\u0646 \u062c\u0633 \u06a9\u0648 \u0633\u067e\u0648\u0631\u0679 \u062f\u0631\u06a9\u0627\u0631 \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Issue","definition_en":"A question that invites more than one reasonable answer - something people can disagree about and that needs reasoning rather than a single factual lookup.","definition_ur":"\u0627\u06cc\u06a9 \u0633\u0648\u0627\u0644 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u0645\u0639\u0642\u0648\u0644 \u062c\u0648\u0627\u0628 \u0645\u0645\u06a9\u0646 \u06c1\u0648\u06ba - \u0627\u06cc\u0633\u06cc \u0686\u06cc\u0632 \u062c\u0633 \u067e\u0631 \u0644\u0648\u06af \u0627\u062e\u062a\u0644\u0627\u0641 \u06a9\u0631 \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u062c\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0635\u0631\u0641 \u0627\u06cc\u06a9 \u062d\u0642\u06cc\u0642\u062a \u062a\u0644\u0627\u0634 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06d2 \u0627\u0633\u062a\u062f\u0644\u0627\u0644 \u062f\u0631\u06a9\u0627\u0631 \u06c1\u0648\u06d4"},{"term":"Argument","definition_en":"A claim plus at least one reason offered to support it - the claim is the conclusion and the reasons are the premises. In critical thinking this is not a quarrel but a supported case.","definition_ur":"\u0627\u06cc\u06a9 \u062f\u0639\u0648\u06cc \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u0645 \u0627\u0632 \u06a9\u0645 \u0627\u06cc\u06a9 \u0648\u062c\u0648\u06c1\u0627\u062a \u0627\u0633 \u06a9\u06cc \u062d\u0645\u0627\u06cc\u062a \u06a9\u06d2 \u0644\u06cc\u06d2 \u067e\u06cc\u0634 \u06a9\u06cc \u06af\u0626\u06cc - \u062f\u0639\u0648\u06cc \u0646\u062a\u06cc\u062c\u06c1 \u06c1\u06d2 \u0627\u0648\u0631 \u0648\u062c\u0648\u06c1\u0627\u062a \u0645\u0642\u062f\u0645\u0627\u062a\u06d4 \u062a\u0646\u0642\u06cc\u062f\u06cc \u0633\u0648\u0686 \u0645\u06cc\u06ba \u06cc\u06c1 \u062c\u06be\u06af\u0691\u0627 \u0646\u06c1\u06cc\u06ba \u0628\u0644\u06a9\u06c1 \u0627\u06cc\u06a9 \u0645\u0639\u0627\u0648\u0646 \u0645\u0642\u062f\u0645\u06c1 \u06c1\u06d2\u06d4"},{"term":"Curriculum","definition_en":"The teacher\'s answer to four questions: what to teach, in what order, at what pace, and for whom. In this course each of these is treated as a management act that shapes the classroom before the lesson begins.","definition_ur":"\u0627\u0633\u062a\u0627\u062f \u06a9\u06d2 \u0686\u0627\u0631 \u0633\u0648\u0627\u0644\u0648\u06ba \u06a9\u06d2 \u062c\u0648\u0627\u0628\u0627\u062a: \u06a9\u06cc\u0627 \u067e\u0691\u06be\u0627\u0646\u0627 \u06c1\u06d2\u060c \u06a9\u0633 \u062a\u0631\u062a\u06cc\u0628 \u0645\u06cc\u06ba\u060c \u06a9\u0633 \u0631\u0641\u062a\u0627\u0631 \u0633\u06d2\u060c \u0627\u0648\u0631 \u06a9\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2\u06d4 \u0627\u0633 \u06a9\u0648\u0631\u0633 \u0645\u06cc\u06ba \u0627\u0646 \u0645\u06cc\u06ba \u0633\u06d2 \u06c1\u0631 \u0627\u06cc\u06a9 \u06a9\u0648 \u0627\u06cc\u06a9 \u0627\u0646\u062a\u0638\u0627\u0645\u06cc \u0639\u0645\u0644 \u06a9\u06d2 \u0637\u0648\u0631 \u067e\u0631 \u0644\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2 \u062c\u0648 \u0633\u0628\u0642 \u0633\u06d2 \u067e\u06c1\u0644\u06d2 \u06c1\u06cc \u06a9\u0644\u0627\u0633 \u06a9\u06cc \u0634\u06a9\u0644 \u0628\u0646\u0627\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Lesson planning","definition_en":"The stage in which the teacher decides the learning target, the activities, the materials, and the time each part of the lesson will take. The management decision at this stage is clarity of target.","definition_ur":"\u0648\u06c1 \u0645\u0631\u062d\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u0633\u062a\u0627\u062f \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u06a9\u0627 \u0645\u0642\u0635\u062f\u060c \u0633\u0631\u06af\u0631\u0645\u06cc\u0627\u06ba\u060c \u0645\u0648\u0627\u062f\u060c \u0627\u0648\u0631 \u0633\u0628\u0642 \u06a9\u06d2 \u06c1\u0631 \u062d\u0635\u06d2 \u06a9\u0627 \u0648\u0642\u062a \u0637\u06d2 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u0633 \u0645\u0631\u062d\u0644\u06d2 \u06a9\u0627 \u0627\u0646\u062a\u0638\u0627\u0645\u06cc \u0641\u06cc\u0635\u0644\u06c1 \u0645\u0642\u0635\u062f \u06a9\u06cc \u0648\u0636\u0627\u062d\u062a \u06c1\u06d2\u06d4"},{"term":"Motivation","definition_en":"The stage in which the teacher creates the want to learn before the teaching begins. The management decision at this stage is relevance: pupils who can see why the lesson matters to them are easier to teach.","definition_ur":"\u0648\u06c1 \u0645\u0631\u062d\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u0633\u062a\u0627\u062f \u062a\u062f\u0631\u06cc\u0633 \u0633\u06d2 \u067e\u06c1\u0644\u06d2 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u06a9\u06cc \u062e\u0648\u0627\u06c1\u0634 \u067e\u06cc\u062f\u0627 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u0633 \u0645\u0631\u062d\u0644\u06d2 \u06a9\u0627 \u0627\u0646\u062a\u0638\u0627\u0645\u06cc \u0641\u06cc\u0635\u0644\u06c1 \u0645\u0637\u0627\u0628\u0642\u062a \u06c1\u06d2: \u0648\u06c1 \u0634\u0627\u06af\u0631\u062f \u062c\u0648 \u062f\u06cc\u06a9\u06be \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba \u06a9\u06c1 \u0633\u0628\u0642 \u0627\u0646 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06a9\u06cc\u0648\u06ba \u0627\u06c1\u0645 \u06c1\u06d2\u060c \u0627\u0646 \u06a9\u06cc \u062a\u062f\u0631\u06cc\u0633 \u0622\u0633\u0627\u0646 \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Assessment","definition_en":"The stage in which the teacher checks whether the learning target has been met. The management decision at this stage is evidence: a teacher who ends the lesson without checking is managing on hope.","definition_ur":"\u0648\u06c1 \u0645\u0631\u062d\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u0633\u062a\u0627\u062f \u06cc\u06c1 \u062f\u06cc\u06a9\u06be\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u06a9\u0627 \u0645\u0642\u0635\u062f \u067e\u0648\u0631\u0627 \u06c1\u0648\u0627 \u06cc\u0627 \u0646\u06c1\u06cc\u06ba\u06d4 \u0627\u0633 \u0645\u0631\u062d\u0644\u06d2 \u06a9\u0627 \u0627\u0646\u062a\u0638\u0627\u0645\u06cc \u0641\u06cc\u0635\u0644\u06c1 \u062b\u0628\u0648\u062a \u06c1\u06d2: \u062c\u0648 \u0627\u0633\u062a\u0627\u062f \u0628\u063a\u06cc\u0631 \u062c\u0627\u0646\u0686\u06d2 \u0633\u0628\u0642 \u062e\u062a\u0645 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u060c \u0648\u06c1 \u0627\u0645\u06cc\u062f \u067e\u0631 \u0627\u0646\u062a\u0638\u0627\u0645 \u06a9\u0631 \u0631\u06c1\u0627 \u06c1\u06d2\u06d4"},{"term":"Differentiation","definition_en":"Adjusting the content, the process, or the product of a lesson so that every pupil works at the edge of their current ability while reaching the same target. It does not mean making some children do easier work.","definition_ur":"\u0633\u0628\u0642 \u06a9\u06d2 \u0645\u0648\u0627\u062f\u060c \u0639\u0645\u0644\u060c \u06cc\u0627 \u0646\u062a\u06cc\u062c\u06d2 \u06a9\u0648 \u0627\u0633 \u0637\u0631\u062d \u0627\u06cc\u0688\u062c\u0633\u0679 \u06a9\u0631\u0646\u0627 \u06a9\u06c1 \u06c1\u0631 \u0634\u0627\u06af\u0631\u062f \u0627\u067e\u0646\u06cc \u0645\u0648\u062c\u0648\u062f\u0627 \u0635\u0644\u0627\u062d\u06cc\u062a \u06a9\u06cc \u062d\u062f \u062a\u06a9 \u06a9\u0627\u0645 \u06a9\u0631\u06d2 \u0627\u0648\u0631 \u0633\u0627\u062a\u06be \u06c1\u06cc \u0627\u06cc\u06a9 \u062c\u06cc\u0633\u06d2 \u0645\u0642\u0635\u062f \u06a9\u0648 \u067e\u06c1\u0646\u0686\u06d2\u06d4 \u0627\u0633 \u0633\u06d2 \u0645\u0631\u0627\u062f \u06cc\u06c1 \u0646\u06c1\u06cc\u06ba \u06a9\u06c1 \u06a9\u0686\u06be \u0628\u0686\u0648\u06ba \u06a9\u0648 \u0622\u0633\u0627\u0646 \u06a9\u0627\u0645 \u062f\u06cc\u0627 \u062c\u0627\u0626\u06d2\u06d4"},{"term":"Multigrade classroom","definition_en":"A classroom in which a single teacher is responsible for pupils of two or more grade levels at the same time, in the same room. It requires management tactics, such as anchor activities and peer tutoring, that a single-grade classroom does not.","definition_ur":"\u0627\u06cc\u0633\u0627 \u06a9\u0644\u0627\u0633 \u0631\u0648\u0645 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u06c1\u06cc \u0627\u0633\u062a\u0627\u062f \u0627\u06cc\u06a9 \u06c1\u06cc \u0648\u0642\u062a \u0627\u0648\u0631 \u0627\u06cc\u06a9 \u06c1\u06cc \u06a9\u0645\u0631\u06d2 \u0645\u06cc\u06ba \u062f\u0648 \u06cc\u0627 \u0632\u06cc\u0627\u062f\u06c1 \u062f\u0631\u062c\u0627\u062a \u06a9\u06d2 \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u0627 \u0630\u0645\u06c1 \u062f\u0627\u0631 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u0646\u062a\u0638\u0627\u0645\u06cc \u062d\u06a9\u0645\u062a \u0639\u0645\u0644\u06cc \u062f\u0631\u06a9\u0627\u0631 \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u060c \u062c\u06cc\u0633\u06d2 \u0644\u0646\u06af\u0631 \u0633\u0631\u06af\u0631\u0645\u06cc\u0627\u06ba \u0627\u0648\u0631 \u06c1\u0645 \u0639\u0645\u0631 \u062a\u062f\u0631\u06cc\u0633\u060c \u062c\u0648 \u0648\u0627\u062d\u062f \u062f\u0631\u062c\u06d2 \u06a9\u06d2 \u06a9\u0644\u0627\u0633 \u0631\u0648\u0645 \u0645\u06cc\u06ba \u0646\u06c1\u06cc\u06ba \u0686\u0627\u06c1\u06cc\u06ba\u06d4"},{"term":"Overcrowded classroom","definition_en":"A classroom in which the number of pupils far exceeds the room\'s designed capacity. The management problem is not just space but the near-impossibility of individual attention at that scale.","definition_ur":"\u0627\u06cc\u0633\u0627 \u06a9\u0644\u0627\u0633 \u0631\u0648\u0645 \u062c\u0633 \u0645\u06cc\u06ba \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u06cc \u062a\u0639\u062f\u0627\u062f \u06a9\u0645\u0631\u06d2 \u06a9\u06cc \u0688\u06cc\u0632\u0627\u0626\u0646 \u0634\u062f\u06c1 \u06af\u0646\u062c\u0627\u0626\u0634 \u0633\u06d2 \u0628\u06c1\u062a \u0632\u06cc\u0627\u062f\u06c1 \u06c1\u0648\u06d4 \u0627\u0646\u062a\u0638\u0627\u0645\u06cc \u0645\u0633\u0626\u0644\u06c1 \u0635\u0631\u0641 \u062c\u06af\u06c1 \u0646\u06c1\u06cc\u06ba \u0628\u0644\u06a9\u06c1 \u0627\u0633 \u067e\u06cc\u0645\u0627\u0646\u06d2 \u067e\u0631 \u0627\u0646\u0641\u0631\u0627\u062f\u06cc \u062a\u0648\u062c\u06c1 \u062f\u06cc\u0646\u06d2 \u06a9\u06cc \u062a\u0642\u0631\u06cc\u0628\u0627\u064b \u0646\u0627\u0645\u0645\u06a9\u0646\u06cc\u062a \u06c1\u06d2\u06d4"},{"term":"Anchor activity","definition_en":"A task that one group of pupils can do independently while the teacher works with another group. A good anchor activity is self-checking, connected to the current topic, and familiar enough to start without the teacher.","definition_ur":"\u0627\u06cc\u0633\u06cc \u0633\u0631\u06af\u0631\u0645\u06cc \u062c\u0648 \u0627\u06cc\u06a9 \u06af\u0631\u0648\u06c1 \u0622\u0633\u06a9\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Peer tutoring","definition_en":"A structured arrangement in which a pupil who has mastered an explanation teaches it to a peer. It must be structured - the tutor needs a clear role, the tutee a clear task, and the teacher must check that the explanation is correct.","definition_ur":"\u0627\u06cc\u06a9 \u0645\u0646\u0638\u0645 \u0627\u0646\u062a\u0638\u0627\u0645 \u062c\u0633 \u0645\u06cc\u06ba \u0648\u06c1 \u0634\u0627\u06af\u0631\u062f \u062c\u0633 \u0646\u06d2 \u06a9\u0648\u0626\u06cc \u0648\u0636\u0627\u062d\u062a \u0633\u06cc\u06a9\u06be \u0644\u06cc \u06c1\u06d2\u060c \u0627\u0633\u06d2 \u0627\u067e\u0646\u06d2 \u06c1\u0645 \u0639\u0645\u0631 \u06a9\u0648 \u0633\u06a9\u06be\u0627\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u0633\u06d2 \u0645\u0646\u0638\u0645 \u06c1\u0648\u0646\u0627 \u0686\u0627\u06c1\u06cc\u06d2 - \u0627\u062a\u062f\u0631\u06cc\u0633 \u06a9\u0648 \u06a9\u0648\u0626\u06cc \u0648\u0627\u0636\u062d \u06a9\u0631\u062f\u0627\u0631 \u0686\u0627\u06c1\u06cc\u06d2\u060c \u0645\u062a\u0631\u0628\u06cc\u0679 \u06a9\u0648 \u06a9\u0648\u0626\u06cc \u0648\u0627\u0636\u062d \u06a9\u0627\u0645 \u0686\u0627\u06c1\u06cc\u06d2\u060c \u0627\u0648\u0631 \u0627\u0633\u062a\u0627\u062f \u06a9\u0648 \u06cc\u06c1 \u062c\u0627\u0646\u0686\u0646\u0627 \u0686\u0627\u06c1\u06cc\u06d2 \u06a9\u06c1 \u0648\u0636\u0627\u062d\u062a \u062f\u0631\u0633\u062a \u06c1\u06d2\u06d4"},{"term":"Routine","definition_en":"A repeated way of doing something that pupils learn to do without being told each time. A routine that has been practised until it is automatic is one of the most powerful time-management tools a teacher has.","definition_ur":"\u06a9\u0633\u06cc \u06a9\u0627\u0645 \u06a9\u0648 \u0628\u0627\u0631 \u0628\u0627\u0631 \u06a9\u0631\u0646\u06d2 \u06a9\u0627 \u0627\u06cc\u0633\u0627 \u0637\u0631\u06cc\u0642\u06c1 \u062c\u0648 \u0634\u0627\u06af\u0631\u062f \u0628\u063a\u06cc\u0631 \u0628\u062a\u0627\u0626\u06d2 \u0633\u06cc\u06a9\u06be \u062c\u0627\u0626\u06cc\u06ba\u06d4 \u0627\u06cc\u0633\u0627 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u062c\u0648 \u0627\u062a\u0646\u0627 \u0645\u0634\u0642 \u0634\u062f\u06c1 \u06c1\u0648 \u06a9\u06d2 \u062e\u0648\u062f\u06a9\u0627\u0631 \u06c1\u0648 \u062c\u0627\u0626\u06d2\u060c \u0627\u0633\u062a\u0627\u062f \u06a9\u06d2 \u067e\u0627\u0633 \u0648\u0642\u062a \u06a9\u06d2 \u0627\u0646\u062a\u0638\u0627\u0645 \u06a9\u0627 \u0633\u0628 \u0633\u06d2 \u0637\u0627\u0642\u062a\u0648\u0631 \u0622\u0644\u06c1 \u06c1\u06d2\u06d4"},{"term":"Structure","definition_en":"The framework that holds routines: the timetable, the seating arrangement, the way the room is organised for group work. A structure without routines is just furniture; routines without a structure have nowhere to live.","definition_ur":"\u0648\u06c1 \u0688\u06be\u0627\u0646\u0686\u06c1 \u062c\u0648 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u06a9\u0648 \u0627\u0679\u06be\u0627\u0626\u06d2 \u0631\u06a9\u06be\u062a\u0627 \u06c1\u06d2: \u0679\u0627\u0626\u0645 \u0679\u06cc\u0628\u0644\u060c \u0646\u0634\u0633\u062a\u0648\u06ba \u06a9\u0627 \u0627\u0646\u062a\u0638\u0627\u0645\u060c \u06cc\u0627 \u06af\u0631\u0648\u06c1 \u06a9\u0627\u0645 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06a9\u0645\u0631\u06d2 \u06a9\u0627 \u0627\u0646\u062a\u0638\u0627\u0645\u06d4 \u062f\u0633\u062a\u0648\u0631 \u0639\u0645\u0644 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u0688\u06be\u0627\u0646\u0688\u06c1 \u0635\u0631\u0641 \u0641\u0631\u0646\u06cc\u0686\u0631 \u06c1\u06d2\u061b \u0688\u06be\u0627\u0646\u0686\u06d2 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u06a9\u0648 \u0631\u06c1\u0646\u06d2 \u06a9\u06cc \u062c\u06af\u06c1 \u0646\u06c1\u06cc\u06ba \u0645\u0644\u062a\u06cc\u06d4"},{"term":"Procedure","definition_en":"A step-by-step sequence for a specific task: how to sharpen a pencil, how to line up, how to hand in homework. A procedure is taught once and followed many times.","definition_ur":"\u06a9\u0633\u06cc \u0645\u062e\u0635\u0648\u0635 \u06a9\u0627\u0645 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0642\u062f\u0645 \u0628\u06c1 \u0642\u062f\u0645 \u062a\u0631\u062a\u06cc\u0628: \u067e\u0646\u0633\u0644 \u06a9\u06cc\u0633\u06d2 \u0686\u06be\u06cc\u0646\u06cc \u062c\u0627\u0626\u06d2\u060c \u0642\u0637\u0627\u0631 \u06a9\u06cc\u0633\u06d2 \u0628\u0646\u0627\u0626\u06cc \u062c\u0627\u0626\u06d2\u060c \u06c1\u0645 \u0648\u0631\u06a9 \u06a9\u06cc\u0633\u06d2 \u062c\u0645\u0639 \u06a9\u0631\u0627\u06cc\u0627 \u062c\u0627\u0626\u06d2\u06d4 \u0627\u06cc\u06a9 \u0637\u0631\u06cc\u0642\u06c1 \u06a9\u0627\u0631 \u0627\u06cc\u06a9 \u0628\u0627\u0631 \u0633\u06a9\u06be\u0627\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0628\u0627\u0631 \u0628\u0627\u0631 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Rule","definition_en":"A statement of what is allowed or expected in a classroom. A rule sets a boundary; a routine removes the need to enforce that boundary by building the behaviour behind it.","definition_ur":"\u06a9\u0644\u0627\u0633 \u0645\u06cc\u06ba \u0627\u062c\u0627\u0632\u062a \u06cc\u0627 \u062a\u0648\u0642\u0639 \u06a9\u0627 \u0628\u06cc\u0627\u0646\u06d4 \u0627\u06cc\u06a9 \u0627\u0635\u0648\u0644 \u062d\u062f \u0642\u0627\u0626\u0645 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u061b \u0627\u06cc\u06a9 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u0627\u0633 \u062d\u062f \u06a9\u0627 \u0646\u0641\u0627\u0630 \u06a9\u0631\u0646\u06d2 \u06a9\u06cc \u0636\u0631\u0648\u0631\u062a \u062e\u062a\u0645 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06d2 \u067e\u06cc\u0686\u06be\u06d2 \u0631\u0648\u06cc\u06c1 \u0628\u0646\u0627\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Anchor routine","definition_en":"The routine a group of pupils follows while the teacher works with another group. A good anchor routine is self-checking, connected to the current topic, and familiar enough that the teacher is not interrupted.","definition_ur":"\u0648\u06c1 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u062c\u0648 \u0627\u06cc\u06a9 \u06af\u0631\u0648\u06c1 \u0627\u0633\u062a\u0627\u062f \u062f\u0648\u0633\u0631\u06d2 \u06af\u0631\u0648\u06c1 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u0627\u0645 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u062f\u0648\u0631\u0627\u0646 \u0628\u0631\u0642\u0631\u0627\u0631 \u0631\u06a9\u06be\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u06cc\u06a9 \u0627\u0686\u06be\u0627 \u0644\u0646\u06af\u0631 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u062e\u0648\u062f \u062c\u0627\u0646\u0686 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u060c \u0645\u0648\u062c\u0648\u062f\u06c1 \u0645\u0648\u0636\u0648\u0639 \u0633\u06d2 \u062c\u0691\u0627 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u060c \u0627\u0648\u0631 \u0627\u062a\u0646\u0627 \u0645\u0627\u0646\u0648\u0633 \u06c1\u0648\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u0627\u0633\u062a\u0627\u062f \u0645\u06cc\u06ba \u0645\u062f\u062f \u0646\u06c1\u06cc\u06ba \u0645\u0627\u0646\u06af\u062a\u06cc\u06d4"},{"term":"Independent-work routine","definition_en":"The routine that governs what pupils do when working alone: how to get materials, how to ask for help without calling out, what to do when finished.","definition_ur":"\u0648\u06c1 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u062c\u0648 \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u06d2 \u0622\u0632\u0627\u062f \u06a9\u0627\u0645 \u06a9\u06d2 \u062f\u0648\u0631\u0627\u0646 \u0644\u0627\u06af\u0648 \u06c1\u0648\u062a\u0627 \u06c1\u06d2: \u0645\u0648\u0627\u062f \u06a9\u06cc\u0633\u06d2 \u062d\u0627\u0635\u0644 \u06a9\u0631\u06cc\u06ba\u060c \u0628\u0646\u0627 \u0686\u06cc\u062e\u06d2 \u0645\u062f\u062f \u06a9\u06cc\u0633\u06d2 \u0645\u0627\u0646\u06af\u06cc\u06ba\u060c \u062e\u062a\u0645 \u06c1\u0648\u0646\u06d2 \u067e\u0631 \u06a9\u06cc\u0627 \u06a9\u0631\u06cc\u06ba\u06d4"},{"term":"Checking routine","definition_en":"A routine that governs how pupils get feedback without queuing for the teacher: self-checking, peer-checking, or traffic-light cards.","definition_ur":"\u0627\u06cc\u0633\u0627 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u062c\u0648 \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u0648 \u0627\u0633\u062a\u0627\u062f \u06a9\u06d2 \u0627\u0646\u062a\u0638\u0627\u0631 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u0631\u0627\u0626\u06d2 \u062d\u0627\u0635\u0644 \u06a9\u0631\u0646\u06d2 \u06a9\u0627 \u0637\u0631\u06cc\u0642\u06c1 \u0628\u062a\u0627\u062a\u0627 \u06c1\u06d2: \u062e\u0648\u062f \u062c\u0627\u0646\u0686\u060c \u06c1\u0645 \u0639\u0645\u0631 \u062c\u0627\u0646\u0686\u060c \u06cc\u0627 \u0679\u0631\u06cc\u0641\u06a9 \u0644\u0627\u0626\u0679 \u06a9\u0627\u0631\u0688\u0632\u06d4"},{"term":"Collaborative learning","definition_en":"Pupils working together toward a shared goal with individual accountability: every pupil has a role, every role is necessary, and the group cannot succeed unless every member contributes.","definition_ur":"\u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u0627 \u0627\u0646\u0641\u0631\u0627\u062f\u06cc \u062c\u0648\u0627\u0628\u062f\u06c1\u06cc \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0645\u0634\u062a\u0631\u06a9\u06c1 \u06c1\u062f\u0641 \u06a9\u06cc \u0637\u0631\u0641 \u0645\u0644 \u06a9\u0631 \u06a9\u0627\u0645 \u06a9\u0631\u0646\u0627: \u06c1\u0631 \u0634\u0627\u06af\u0631\u062f \u06a9\u0627 \u06a9\u0631\u062f\u0627\u0631 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u060c \u06c1\u0631 \u06a9\u0631\u062f\u0627\u0631 \u0636\u0631\u0648\u0631\u06cc \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u060c \u0627\u0648\u0631 \u06af\u0631\u0648\u06c1 \u0627\u0633 \u0648\u0642\u062a \u06a9\u0627\u0645\u06cc\u0627\u0628 \u0646\u06c1\u06cc\u06ba \u06c1\u0648 \u0633\u06a9\u062a\u0627 \u062c\u0628 \u062a\u06a9 \u06c1\u0631 \u0631\u06a9\u0646 \u062d\u0635\u06c1 \u0646\u06c1 \u0688\u0627\u0644\u06d2\u06d4"},{"term":"Individual accountability","definition_en":"The requirement that every member of a group has a necessary role and that the group cannot succeed unless every member contributes. Without it, group work becomes one pupil doing the work while others watch.","definition_ur":"\u0648\u06c1 \u062a\u0642\u0627\u0636\u06c1 \u06a9\u06c1 \u06af\u0631\u0648\u06c1 \u06a9\u06d2 \u06c1\u0631 \u0631\u06a9\u0646 \u06a9\u0627 \u06a9\u0631\u062f\u0627\u0631 \u0636\u0631\u0648\u0631\u06cc \u06c1\u0648 \u0627\u0648\u0631 \u06af\u0631\u0648\u06c1 \u0627\u0633 \u0648\u0642\u062a \u06a9\u0627\u0645\u06cc\u0627\u0628 \u0646\u06c1\u06cc\u06ba \u06c1\u0648 \u0633\u06a9\u062a\u0627 \u062c\u0628 \u062a\u06a9 \u06c1\u0631 \u0631\u06a9\u0646 \u062d\u0635\u06c1 \u0646\u06c1 \u0688\u0627\u0644\u06d2\u06d4 \u0627\u0633 \u06a9\u06d2 \u0628\u063a\u06cc\u0631\u060c \u06af\u0631\u0648\u06c1 \u06a9\u0627\u0645 \u0627\u06cc\u06a9 \u0634\u0627\u06af\u0631\u062f \u06a9\u0627 \u06a9\u0631\u0646\u0627 \u0627\u0648\u0631 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u0627 \u062f\u06cc\u06a9\u06be\u0646\u0627 \u0628\u0646 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Co-operative structure","definition_en":"A way of organising pupils so they work in the same space toward a shared task, helping each other as needed. Think-pair-share, round-robin and numbered heads are co-operative structures.","definition_ur":"\u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u0648 \u0645\u0646\u0638\u0645 \u06a9\u0631\u0646\u06d2 \u06a9\u0627 \u0627\u06cc\u0633\u0627 \u0637\u0631\u06cc\u0642\u06c1 \u06a9\u06c1 \u0648\u06c1 \u0627\u06cc\u06a9 \u06c1\u06cc \u062c\u06af\u06c1 \u0645\u0634\u062a\u0631\u06a9\u06c1 \u06a9\u0627\u0645 \u06a9\u0631\u0648\u06ba \u0627\u0648\u0631 \u0636\u0631\u0648\u0631\u062a \u067e\u0691\u0646\u06d2 \u067e\u0631 \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06cc \u0645\u062f\u062f \u06a9\u0631\u06cc\u06ba\u06d4 \u062a\u06be\u0646\u06a9 \u067e\u0626\u06cc\u0631 \u0634\u06cc\u0626\u0631\u060c \u0631\u0627\u0624\u0646\u0688 \u0631\u0627\u0628\u06cc\u0646 \u0627\u0648\u0631 \u0646\u0645\u0628\u0631\u0688 \u06c1\u06cc\u0688\u0632 \u062a\u0639\u0627\u0648\u0646\u06cc \u0688\u06be\u0627\u0646\u0686\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Community","definition_en":"The set of relationships that surround a classroom: the classroom itself, the school, the parents and families, and the local community. Each circle has a different relationship with the school and a different management demand.","definition_ur":"\u0648\u06c1 \u0631\u0634\u062a\u06d2 \u062c\u0648 \u06a9\u0644\u0627\u0633 \u06a9\u06d2 \u0627\u0631\u062f \u06af\u0631\u062f \u06c1\u0648\u062a\u06d2 \u06c1\u06cc\u06ba: \u06a9\u0644\u0627\u0633 \u062e\u0648\u062f\u060c \u0627\u0633\u06a9\u0648\u0644\u060c \u0648\u0627\u0644\u062f\u06cc\u0646 \u0627\u0648\u0631 \u062e\u0627\u0646\u062f\u0627\u0646\u060c \u0627\u0648\u0631 \u0645\u0642\u0627\u0645\u06cc \u0628\u0631\u0627\u062f\u0631\u06cc\u06d4 \u06c1\u0631 \u062d\u0644\u0642\u06d2 \u06a9\u0627 \u0627\u0633\u06a9\u0648\u0644 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0645\u062e\u062a\u0644\u0641 \u0631\u0634\u062a\u06c1 \u06c1\u0648\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0645\u062e\u062a\u0644\u0641 \u0627\u0646\u062a\u0638\u0627\u0645\u06cc \u062a\u0642\u0627\u0636\u06c1 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Participation","definition_en":"Being present at a school event or contributing to it. Participation is necessary but not sufficient for genuine community involvement.","definition_ur":"\u0627\u0633\u06a9\u0648\u0644 \u06a9\u06d2 \u06a9\u0633\u06cc \u067e\u0631\u0648\u06af\u0631\u0627\u0645 \u0645\u06cc\u06ba \u0634\u0631\u06a9\u062a \u06a9\u0631\u0646\u0627 \u06cc\u0627 \u0627\u0633 \u0645\u06cc\u06ba \u062d\u0635\u06c1 \u0688\u0627\u0644\u0646\u0627\u06d4 \u0634\u0631\u06a9\u062a \u0636\u0631\u0648\u0631\u06cc \u06c1\u06d2 \u0644\u06cc\u06a9\u0646 \u062d\u0642\u06cc\u0642\u06cc \u0628\u0631\u0627\u062f\u0631\u06cc \u0634\u0645\u0648\u0644\u06cc\u062a \u06a9\u06d2 \u0644\u06cc\u06d2 \u06cc\u06c1 \u0627\u06a9\u06cc\u0644\u0627 \u06a9\u0627\u0641\u06cc \u0646\u06c1\u06cc\u06ba\u06d4"},{"term":"Involvement","definition_en":"Having a voice in what happens at a school. Involvement goes beyond participation: a participating parent attends; an involved parent helps decide.","definition_ur":"\u0627\u0633\u06a9\u0648\u0644 \u0645\u06cc\u06ba \u062c\u0648 \u06a9\u0686\u06be \u06c1\u0648\u062a\u0627 \u06c1\u06d2 \u0627\u0633 \u0645\u06cc\u06ba \u0627\u067e\u0646\u06cc \u0631\u0627\u0626\u06d2 \u062f\u06cc\u0646\u0627\u06d4 \u0634\u0645\u0648\u0644\u06cc\u062a \u0634\u0631\u06a9\u062a \u0633\u06d2 \u0622\u06af\u06d2 \u0628\u0691\u06be \u06a9\u0631 \u06c1\u06d2: \u0634\u0631\u06cc\u06a9 \u0648\u0627\u0644\u062f\u06cc\u0646 \u062c\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u061b \u0634\u0627\u0645\u0644 \u0648\u0627\u0644\u062f\u06cc\u0646 \u0641\u06cc\u0635\u0644\u06d2 \u0645\u06cc\u06ba \u0645\u062f\u062f \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Ethic of care","definition_en":"A set of practices built from attentiveness, responsiveness, competence and mutual respect. An ethic of care is not permissiveness: it includes consequences, but they are restorative rather than punitive.","definition_ur":"\u062a\u0648\u062c\u06c1\u060c \u062c\u0648\u0627\u0628\u062f\u06c1\u06cc\u060c \u0635\u0644\u0627\u062d\u06cc\u062a \u0627\u0648\u0631 \u0628\u0627\u06c1\u0645 \u0627\u062d\u062a\u0631\u0627\u0645 \u0633\u06d2 \u0628\u0646\u06d2 \u0639\u0645\u0644 \u06a9\u0627 \u0645\u062c\u0645\u0648\u0639\u06c1\u06d4 \u062f\u06cc\u06a9\u06be \u0628\u06be\u0627\u0644 \u06a9\u0627 \u0627\u062e\u0644\u0627\u0642\u06cc\u0627\u062a \u0628\u06d2 \u0642\u06cc\u062f \u067e\u0646 \u0646\u06c1\u06cc\u06ba \u06c1\u06d2: \u0627\u0633 \u0645\u06cc\u06ba \u0646\u062a\u0627\u0626\u062c \u0634\u0627\u0645\u0644 \u06c1\u06cc\u06ba\u060c \u0644\u06cc\u06a9\u0646 \u0648\u06c1 \u0633\u0632\u0627 \u062f\u06cc\u0646\u06d2 \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06d2 \u0628\u062d\u0627\u0644\u06cc \u06a9\u06d2 \u06c1\u0648\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Personal accountability","definition_en":"The willingness to own the consequences of your actions and to make them right. Personal accountability is the internalised version of discipline: discipline is external (the teacher enforces), accountability is internal (the pupil owns).","definition_ur":"\u0627\u067e\u0646\u06d2 \u0627\u0639\u0645\u0627\u0644 \u06a9\u06d2 \u0646\u062a\u0627\u0626\u062c \u0642\u0628\u0648\u0644 \u06a9\u0631\u0646\u06d2 \u0627\u0648\u0631 \u0627\u0646\u06c1\u06cc\u06ba \u062f\u0631\u0633\u062a \u06a9\u0631\u0646\u06d2 \u06a9\u06cc \u062e\u0648\u0627\u06c1\u0634\u06d4 \u0630\u0627\u062a\u06cc \u062c\u0648\u0627\u0628\u062f\u06c1\u06cc \u0636\u0627\u0628\u0637\u06d2 \u06a9\u0627 \u0627\u0646\u062f\u0631\u0648\u0646\u06cc \u0631\u0648\u067e \u06c1\u06d2: \u0636\u0627\u0628\u0637\u06c1 \u0628\u06cc\u0631\u0648\u0646\u06cc \u06c1\u06d2 (\u0627\u0633\u062a\u0627\u062f \u0646\u0627\u0641\u0630 \u06a9\u0631\u062a\u0627 \u06c1\u06d2)\u060c \u062c\u0648\u0627\u0628\u062f\u06c1\u06cc \u0627\u0646\u062f\u0631\u0648\u0646\u06cc \u06c1\u06d2 (\u0634\u0627\u06af\u0631\u062f \u0642\u0628\u0648\u0644 \u06a9\u0631\u062a\u0627 \u06c1\u06d2)\u06d4"},{"term":"Restorative consequence","definition_en":"A consequence designed to repair the harm caused by a behaviour and to rebuild the relationship, rather than to punish the person. An apology, a repair, or a service to the class are restorative consequences.","definition_ur":"\u0627\u06cc\u0633\u0627 \u0646\u062a\u06cc\u062c\u06c1 \u062c\u0648 \u0631\u0648\u06cc\u06d2 \u06a9\u06cc \u0648\u062c\u06c1 \u0633\u06d2 \u06c1\u0648\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0646\u0642\u0635\u0627\u0646 \u06a9\u0648 \u0679\u06be\u06cc\u06a9 \u06a9\u0631\u0646\u06d2 \u0627\u0648\u0631 \u0631\u0634\u062a\u06d2 \u06a9\u0648 \u0628\u062d\u0627\u0644 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06c1\u0648\u060c \u0634\u062e\u0635 \u06a9\u0648 \u0633\u0632\u0627\u0646\u06c1 \u062f\u06cc\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0646\u06c1\u06cc\u06ba\u06d4 \u0645\u0639\u0630\u0631\u062a\u060c \u0679\u06be\u06cc\u06a9 \u06a9\u0631\u0646\u0627\u060c \u06cc\u0627 \u06a9\u0644\u0627\u0633 \u06a9\u06cc \u062e\u062f\u0645\u062a \u0628\u062d\u0627\u0644\u06cc \u06a9\u06d2 \u0646\u062a\u0627\u0626\u062c \u06c1\u06cc\u06ba\u06d4"},{"term":"Unexpected-event decision aid","definition_en":"A decision framework for when something unplanned happens: the priority order is safety first, then learning, then relationship.","definition_ur":"\u063a\u06cc\u0631 \u0645\u062a\u0648\u0642\u0639 \u0648\u0627\u0642\u0639\u0627\u062a \u06a9\u06d2 \u0644\u06cc\u06d2 \u0641\u06cc\u0635\u0644\u06d2 \u06a9\u0627 \u0688\u06be\u0627\u0646\u0686\u06c1: \u062a\u0631\u062a\u06cc\u0628 \u06a9\u0627 \u062d\u06a9\u0645 \u067e\u06c1\u0644\u06d2 \u062a\u062d\u0641\u0638\u060c \u067e\u06be\u0631 \u0633\u06cc\u06a9\u06be\u0646\u0627\u060c \u067e\u06be\u0631 \u0631\u0634\u062a\u06c1 \u06c1\u06d2\u06d4"},{"term":"Classroom management plan","definition_en":"The course\'s culminating artefact: a document that states a philosophy of learning, describes curriculum decisions, proposes a routine set, and explains how the plan builds care and accountability, all justified by reference to a described classroom.","definition_ur":"\u06a9\u0648\u0631\u0633 \u06a9\u06cc \u0627\u062e\u062a\u062a\u0627\u0645\u06cc \u062a\u062e\u0644\u06cc\u0642: \u0627\u06cc\u0633\u062a\u0627\u062f \u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u062c\u0648 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u06a9\u0627 \u0641\u0644\u0633\u0641\u06c1 \u0628\u06cc\u0627\u0646 \u06a9\u0631\u062a\u06cc \u06c1\u06d2\u060c \u0646\u0635\u0627\u0628\u06cc \u0641\u06cc\u0635\u0644\u06d2 \u0628\u06cc\u0627\u0646 \u06a9\u0631\u062a\u06cc \u06c1\u06d2\u060c \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u06a9\u0627 \u0645\u062c\u0645\u0648\u0639\u06c1 \u062a\u062c\u0648\u06cc\u0632 \u06a9\u0631\u062a\u06cc \u06c1\u06d2\u060c \u0627\u0648\u0631 \u0628\u062a\u0627\u062a\u06cc \u06c1\u06d2 \u06a9\u06c1 \u0645\u0646\u0635\u0648\u0628\u06c1 \u062f\u06cc\u06a9\u06be \u0628\u06be\u0627\u0644 \u0627\u0648\u0631 \u062c\u0648\u0627\u0628\u062f\u06c1\u06cc \u06a9\u06cc\u0633\u06d2 \u0628\u0646\u0627\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Peer critique","definition_en":"A structured protocol for evaluating a classroom management plan against three criteria: clarity, consistency and coverage. The reviewer names the gap; the author decides how to revise.","definition_ur":"\u06a9\u0644\u0627\u0633 \u0631\u0648\u0645 \u0627\u0646\u062a\u0638\u0627\u0645 \u0645\u0646\u0635\u0648\u0628\u06d2 \u06a9\u0627 \u062c\u0627\u0626\u0632\u06c1 \u0644\u06cc\u0646\u06d2 \u06a9\u0627 \u0627\u06cc\u06a9 \u0645\u0646\u0638\u0645 \u0637\u0631\u06cc\u0642\u06c1 \u06a9\u0627\u0631: \u0648\u0636\u0627\u062d\u062a\u060c \u06c1\u0645 \u0622\u06c1\u0646\u06af\u06cc \u0627\u0648\u0631 \u062a\u062d\u0641\u0638\u06d4 \u062c\u0627\u0626\u0632\u06c1 \u0644\u06cc\u0646\u06d2 \u0648\u0627\u0644\u0627 \u06a9\u0645\u06cc \u0628\u062a\u0627\u062a\u0627 \u06c1\u06d2\u061b \u0645\u0635\u062d\u062d \u0641\u06cc\u0635\u0644\u06c1 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u06a9\u06cc\u0633\u06d2 \u062a\u0631\u0645\u06cc\u0645 \u06a9\u06cc \u062c\u0627\u0626\u06d2\u06d4"},{"term":"Summary and close","definition_en":"The course\'s closing synthesis: a whole-group event in which each trainee states a belief that changed across the course and cites the evidence for the change.","definition_ur":"\u06a9\u0648\u0631\u0633 \u06a9\u06cc \u0627\u062e\u062a\u062a\u0627\u0645\u06cc \u062a\u0631\u06a9\u06cc\u0628: \u0627\u06cc\u06a9 \u067e\u0648\u0631\u06d2 \u06af\u0631\u0648\u06c1 \u06a9\u06cc \u062a\u0642\u0631\u06cc\u0628 \u062c\u0633 \u0645\u06cc\u06ba \u06c1\u0631 \u062a\u0631\u0628\u06cc\u062a \u06cc\u0627\u0641\u062a\u06c1 \u0634\u062e\u0635 \u0627\u06cc\u06a9 \u0639\u0642\u06cc\u062f\u06c1 \u0628\u06cc\u0627\u0646 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u062c\u0648 \u06a9\u0648\u0631\u0633 \u06a9\u06d2 \u062f\u0648\u0631\u0627\u0646 \u0628\u062f\u0644 \u06af\u06cc\u0627 \u0627\u0648\u0631 \u062a\u0628\u062f\u06cc\u0644\u06cc \u06a9\u0627 \u062b\u0628\u0648\u062a \u067e\u06cc\u0634 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Vocabulary building","definition_en":"The deliberate process of expanding the words you can use accurately, most effectively through contextual usage rather than memorising word lists.","definition_ur":"\u0627\u0644\u0641\u0627\u0638 \u06a9\u0648 \u062f\u0631\u0633\u062a \u0637\u0631\u06cc\u0642\u06d2 \u0633\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u0646\u06d2 \u06a9\u06cc \u0635\u0644\u0627\u062d\u06cc\u062a \u06a9\u0648 \u0628\u0691\u06be\u0627\u0646\u06d2 \u06a9\u0627 \u0627\u06cc\u06a9 \u0645\u0646\u0638\u0645 \u0639\u0645\u0644\u060c \u062c\u0633 \u0645\u06cc\u06ba \u0627\u0644\u0641\u0627\u0638 \u06a9\u0648 \u0633\u06cc\u0627\u0642 \u0648 \u0633\u0628\u0627\u0642 \u0645\u06cc\u06ba \u0633\u06cc\u06a9\u06be\u0646\u0627 \u0627\u0646 \u06a9\u06cc \u0641\u06c1\u0633\u062a \u06cc\u0627\u062f \u06a9\u0631\u0646\u06d2 \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u0645\u0624\u062b\u0631 \u06c1\u06d2\u06d4"},{"term":"Synonym","definition_en":"A word with a similar meaning to another word. Synonyms are not interchangeable: they differ in shade of meaning, register and collocation.","definition_ur":"\u06a9\u0633\u06cc \u062f\u0648\u0633\u0631\u06d2 \u0644\u0641\u0638 \u06a9\u06d2 \u0645\u0634\u062a\u0631\u06a9\u06d2 \u0645\u0639\u0646\u06cc \u0648\u0627\u0644\u0627 \u0644\u0641\u0638\u06d4 \u0645\u062a\u0631\u0627\u062f\u0641\u0627\u062a \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06cc \u062c\u06af\u06c1 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0646\u06c1\u06cc\u06ba \u06c1\u0648 \u0633\u06a9\u062a\u06d2: \u0627\u0646 \u0645\u06cc\u06ba \u0645\u0639\u0646\u06cc \u06a9\u0627 \u062f\u0631\u062c\u06c1\u060c \u0633\u0637\u062d \u0627\u0648\u0631 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0645\u062e\u062a\u0644\u0641 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Antonym","definition_en":"A word with the opposite meaning of another word. Knowing antonyms helps you understand a word more precisely and gives you tools for contrast in writing.","definition_ur":"\u06a9\u0633\u06cc \u062f\u0648\u0633\u0631\u06d2 \u0644\u0641\u0638 \u06a9\u06d2 \u0645\u062a\u0636\u0627\u062f \u0645\u0639\u0646\u06cc \u0648\u0627\u0644\u0627 \u0644\u0641\u0638\u06d4 \u0645\u062a\u0636\u0627\u062f \u062c\u0627\u0646\u0646\u06d2 \u0633\u06d2 \u0622\u067e \u06a9\u0633\u06cc \u0644\u0641\u0638 \u06a9\u0648 \u0632\u06cc\u0627\u062f\u06c1 \u062f\u0631\u0633\u062a \u0633\u0645\u062c\u06be\u062a\u06d2 \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u062a\u062d\u0631\u06cc\u0631 \u0645\u06cc\u06ba \u062a\u0636\u0627\u062f \u06a9\u06d2 \u0644\u06cc\u06d2 \u0648\u0633\u0627\u0626\u0644 \u0645\u0644\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Idiomatic expression","definition_en":"A phrase whose meaning cannot be worked out from the individual words. Idioms must be learned as whole units because their meaning is figurative, not literal.","definition_ur":"\u0627\u06cc\u06a9 \u0627\u06cc\u0633\u0627 \u0641\u0642\u0631\u06c1 \u062c\u0633 \u06a9\u0627 \u0645\u0639\u0646\u06cc \u0627\u0646\u0641\u0631\u0627\u062f\u06cc \u0627\u0644\u0641\u0627\u0638 \u0633\u06d2 \u0646\u06c1\u06cc\u06ba \u0633\u0645\u062c\u06be\u0627 \u062c\u0627 \u0633\u06a9\u062a\u0627\u06d4 \u0645\u062d\u0627\u0648\u0631\u0648\u06ba \u06a9\u0648 \u0645\u06a9\u0637\u0648\u0631\u0648\u06ba \u06a9\u06d2 \u0637\u0648\u0631 \u067e\u0631 \u0633\u06cc\u06a9\u06be\u0646\u0627 \u0636\u0631\u0648\u0631\u06cc \u06c1\u06d2 \u06a9\u06cc\u0648\u0646\u06a9\u06c1 \u0627\u0646 \u06a9\u06d2 \u0645\u0639\u0627\u0646\u06cc \u0639\u0644\u0627\u0645\u062a\u06cc \u06c1\u0648\u062a\u06d2 \u06c1\u06cc\u06ba\u060c \u0644\u0641\u0638\u06cc \u0646\u06c1\u06cc\u06ba\u06d4"},{"term":"Affixation","definition_en":"Adding a prefix (at the beginning) or a suffix (at the end) to a root word to create a new word. The most productive word-formation process in English.","definition_ur":"\u06a9\u0633\u06cc \u0628\u0646\u06cc\u0627\u062f\u06cc \u0644\u0641\u0638 \u0645\u06cc\u06ba \u0633\u0627\u0628\u0642\u06c1 (\u0634\u0631\u0648\u0639 \u0645\u06cc\u06ba) \u06cc\u0627 \u0644\u0627\u062d\u0642\u06c1 (\u0622\u062e\u0631 \u0645\u06cc\u06ba) \u0634\u0627\u0645\u0644 \u06a9\u0631\u06a9\u06d2 \u0646\u06cc\u0627 \u0644\u0641\u0638 \u0628\u0646\u0627\u0646\u0627\u06d4 \u0627\u0646\u06af\u0631\u06cc\u0632\u06cc \u0645\u06cc\u06ba \u0627\u0644\u0641\u0627\u0638 \u06a9\u06cc \u062a\u0634\u06a9\u06cc\u0644 \u06a9\u0627 \u0633\u0628 \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u0645\u0624\u062b\u0631 \u0639\u0645\u0644\u06d4"},{"term":"Compounding","definition_en":"Joining two complete words to make a new one. The meaning of the compound is often more than the sum of its parts.","definition_ur":"\u062f\u0648 \u0645\u06a9\u0645\u0644 \u0627\u0644\u0641\u0627\u0638 \u06a9\u0648 \u0645\u0644\u0627\u0646\u06d2 \u0633\u06d2 \u0627\u06cc\u06a9 \u0646\u06cc\u0627 \u0644\u0641\u0638 \u0628\u0646\u0627\u0646\u0627\u06d4 \u0645\u0631\u06a9\u0628 \u0644\u0641\u0638 \u06a9\u0627 \u0645\u0639\u0646\u06cc \u0627\u06a9\u062b\u0631 \u0627\u0633 \u06a9\u06d2 \u062d\u0635\u0648\u06ba \u06a9\u06d2 \u0645\u062c\u0645\u0648\u0639\u06d2 \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Clipping","definition_en":"Shortening a longer word to create an informal variant. Common in informal English.","definition_ur":"\u06a9\u0633\u06cc \u0637\u0648\u06cc\u0644 \u0644\u0641\u0638 \u06a9\u0648 \u0686\u06be\u0648\u0679\u0627 \u06a9\u0631\u06a9\u06d2 \u0627\u06cc\u06a9 \u063a\u06cc\u0631 \u0631\u0633\u0645\u06cc \u0635\u0648\u0631\u062a \u0628\u0646\u0627\u0646\u0627\u06d4 \u063a\u06cc\u0631 \u0631\u0633\u0645\u06cc \u0627\u0646\u06af\u0631\u06cc\u0632\u06cc \u0645\u06cc\u06ba \u0639\u0627\u0645 \u06c1\u06d2\u06d4"},{"term":"Back formation","definition_en":"Creating a new word by removing what looks like an affix from an existing word.","definition_ur":"\u06a9\u0633\u06cc \u0645\u0648\u062c\u0648\u062f\u06c1 \u0644\u0641\u0638 \u0633\u06d2 \u0627\u06cc\u06a9 \u0627\u06cc\u0633\u0627 \u062d\u0635\u06c1 \u06c1\u0679\u0627\u0646\u06d2 \u0633\u06d2 \u0646\u06cc\u0627 \u0644\u0641\u0638 \u0628\u0646\u0627\u0646\u0627 \u062c\u0648 \u0644\u0627\u062d\u0642\u06c1 \u06cc\u0627 \u0633\u0627\u0628\u0642\u06c1 \u062f\u06a9\u06be\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Subject-verb agreement","definition_en":"The rule that a verb must match its subject in number: singular subjects take singular verbs, plural subjects take plural verbs.","definition_ur":"\u0648\u06c1 \u0627\u0635\u0648\u0644 \u062c\u0633 \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u0641\u0639\u0644 \u06a9\u0627 \u0641\u0627\u0639\u0644 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u062a\u0639\u062f\u0627\u062f \u0645\u06cc\u06ba \u06c1\u0645 \u0622\u06c1\u0646\u06af \u06c1\u0648\u0646\u0627 \u0636\u0631\u0648\u0631\u06cc \u06c1\u06d2: \u0648\u0627\u062d\u062f \u0641\u0627\u0639\u0644 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0648\u0627\u062d\u062f \u0641\u0639\u0644\u060c \u062c\u0645\u0639 \u0641\u0627\u0639\u0644 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u062c\u0645\u0639 \u0641\u0639\u0644\u06d4"},{"term":"Verb tense","definition_en":"The form of a verb that tells the reader when an action happens: past, present or future.","definition_ur":"\u0641\u0639\u0644 \u06a9\u06cc \u0648\u06c1 \u0635\u0648\u0631\u062a \u062c\u0648 \u0642\u0627\u0631\u06cc \u06a9\u0648 \u0628\u062a\u0627\u062a\u06cc \u06c1\u06d2 \u06a9\u06c1 \u06a9\u0648\u0626\u06cc \u0639\u0645\u0644 \u06a9\u0628 \u06c1\u0648\u0627: \u0645\u0627\u0636\u06cc\u060c \u062d\u0627\u0644 \u06cc\u0627 \u0645\u0633\u062a\u0642\u0628\u0644\u06d4"},{"term":"Fragment","definition_en":"An incomplete sentence missing a subject, a verb, or both.","definition_ur":"\u0627\u06cc\u06a9 \u0646\u0627\u0645\u06a9\u0645\u0644 \u062c\u0645\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0641\u0627\u0639\u0644\u060c \u0641\u0639\u0644 \u06cc\u0627 \u062f\u0648\u0646\u0648\u06ba \u063a\u0627\u0626\u0628 \u06c1\u0648\u06ba\u06d4"},{"term":"Run-on sentence","definition_en":"Two complete sentences joined without proper punctuation or a conjunction.","definition_ur":"\u062f\u0648 \u0645\u06a9\u0645\u0644 \u062c\u0645\u0644\u0648\u06ba \u06a9\u0648 \u0645\u0646\u0627\u0633\u0628 \u0631\u0645\u0627\u06a9\u0627\u0646 \u06cc\u0627 \u062d\u0631\u0641 \u0639\u0637\u0641 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u062c\u0648\u0691\u0646\u06d2 \u0633\u06d2 \u0628\u0646\u0646\u06d2 \u0648\u0627\u0644\u0627 \u062c\u0645\u0644\u06c1\u06d4"},{"term":"Misplaced modifier","definition_en":"A word or phrase that describes another word but is positioned so that it creates confusion about what is being described.","definition_ur":"\u0627\u06cc\u06a9 \u0644\u0641\u0638 \u06cc\u0627 \u0641\u0642\u0631\u06c1 \u062c\u0648 \u06a9\u0633\u06cc \u062f\u0648\u0633\u0631\u06d2 \u0644\u0641\u0638 \u06a9\u06cc \u0648\u0636\u0627\u062d\u062a \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u0644\u06cc\u06a9\u0646 \u0627\u06cc\u0633\u06cc \u062c\u06af\u06c1 \u0631\u06a9\u06be\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u06cc\u06c1 \u0627\u0644\u062c\u06c1\u0627\u0646 \u067e\u06cc\u062f\u0627 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Article","definition_en":"A word that signals whether a noun is specific or general.","definition_ur":"\u0627\u06cc\u06a9 \u0644\u0641\u0638 \u062c\u0648 \u0627\u0633 \u0628\u0627\u062a \u06a9\u06cc \u0646\u0634\u0627\u0646\u062f\u06c1\u06cc \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u06a9\u0648\u0626\u06cc \u0627\u0633\u0645 \u0645\u062e\u0635\u0648\u0635 \u06c1\u06d2 \u06cc\u0627 \u0639\u0627\u0645\u06d4"},{"term":"Word class","definition_en":"The category a word falls into based on its function in a sentence: noun, verb, adjective, adverb, preposition, conjunction, pronoun or article.","definition_ur":"\u0648\u06c1 \u0632\u0645\u0631\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u06a9\u0648\u0626\u06cc \u0644\u0641\u0638 \u062c\u0645\u0644\u06d2 \u0645\u06cc\u06ba \u0627\u067e\u0646\u06d2 \u06a9\u0627\u0645 \u06a9\u06d2 \u0627\u0639\u062a\u0628\u0627\u0631 \u0633\u06d2 \u0622\u062a\u0627 \u06c1\u06d2: \u0627\u0633\u0645\u060c \u0641\u0639\u0644\u060c \u0635\u0641\u062a\u060c \u0638\u0631\u0641\u060c \u062d\u0631\u0641 \u0631\u0628\u0637\u060c \u062d\u0631\u0641 \u0639\u0637\u0641\u060c \u0636\u0645\u06cc\u0631 \u06cc\u0627 \u062d\u0631\u0641 \u062a\u0639\u0631\u06cc\u0641\u06d4"},{"term":"Simple sentence","definition_en":"A sentence with one independent clause.","definition_ur":"\u0627\u06cc\u06a9 \u062c\u0645\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u0622\u0632\u0627\u062f \u0641\u0642\u0631\u06c1 \u06c1\u0648\u06d4"},{"term":"Compound sentence","definition_en":"A sentence with two independent clauses joined by a coordinating conjunction.","definition_ur":"\u0627\u06cc\u06a9 \u062c\u0645\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u062f\u0648 \u0622\u0632\u0627\u062f \u0641\u0642\u0631\u06d2 \u062f\u0648 \u062d\u0631\u0641 \u0631\u0628\u0637 \u0633\u06d2 \u062c\u0648\u0691\u06d2 \u06af\u0626\u06d2 \u06c1\u0648\u06ba\u06d4"},{"term":"Complex sentence","definition_en":"A sentence with one independent clause and one or more dependent clauses.","definition_ur":"\u0627\u06cc\u06a9 \u062c\u0645\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u0622\u0632\u0627\u062f \u0641\u0642\u0631\u06c1 \u0627\u0648\u0631 \u0627\u06cc\u06a9 \u06cc\u0627 \u0632\u06cc\u0627\u062f\u06c1 \u0648\u0627\u0628\u0633\u062a\u06c1 \u0641\u0642\u0631\u06d2 \u06c1\u0648\u06ba\u06d4"},{"term":"Compound-complex sentence","definition_en":"A sentence with two independent clauses and one or more dependent clauses.","definition_ur":"\u0627\u06cc\u06a9 \u062c\u0645\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u062f\u0648 \u0622\u0632\u0627\u062f \u0641\u0642\u0631\u06d2 \u0627\u0648\u0631 \u0627\u06cc\u06a9 \u06cc\u0627 \u0632\u06cc\u0627\u062f\u06c1 \u0648\u0627\u0628\u0633\u062a\u06c1 \u0641\u0642\u0631\u06d2 \u06c1\u0648\u06ba\u06d4"},{"term":"Editing","definition_en":"The process of improving a text at every level by reading, identifying errors, correcting, reading aloud and repeating until the text is clean.","definition_ur":"\u06c1\u0631 \u0633\u0637\u062d \u067e\u0631 \u0645\u062a\u0646 \u06a9\u0648 \u0628\u06c1\u062a\u0631 \u0628\u0646\u0627\u0646\u06d2 \u06a9\u0627 \u0639\u0645\u0644 - \u067e\u0691\u06be \u06a9\u0631\u060c \u063a\u0644\u0637\u06cc\u0648\u06ba \u06a9\u06cc \u0646\u0634\u0627\u0646\u062f\u06c1\u06cc \u06a9\u0631 \u06a9\u06d2\u060c \u062f\u0631\u0633\u062a \u06a9\u0631 \u06a9\u06d2\u060c \u0628\u0644\u0646\u062f \u0622\u0648\u0627\u0632 \u0633\u06d2 \u067e\u0691\u06be \u06a9\u0631 \u0627\u0648\u0631 \u062a\u06a9\u0631\u0627\u0631 \u06a9\u0631 \u06a9\u06d2\u06d4"},{"term":"Pronunciation","definition_en":"The way in which spoken words are sounded. Clear pronunciation supports clear writing.","definition_ur":"\u0628\u0648\u0644\u06d2 \u062c\u0627\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0627\u0644\u0641\u0627\u0638 \u06a9\u06cc \u0622\u0648\u0627\u0632\u06d4 \u0635\u0627\u0641 \u062a\u0644\u0641\u0638 \u0635\u0627\u0641 \u062a\u062d\u0631\u06cc\u0631 \u06a9\u06cc \u062d\u0645\u0627\u06cc\u062a \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Register","definition_en":"The level of formality that a situation demands in language use.","definition_ur":"\u0632\u0628\u0627\u0646 \u06a9\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0627 \u0648\u06c1 \u0633\u0637\u062d \u062c\u0633\u06d2 \u0635\u0648\u0631\u062a\u062d\u0627\u0644 \u0645\u06cc\u06ba \u0636\u0631\u0648\u0631\u062a \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Collocation","definition_en":"The tendency of certain words to appear together.","definition_ur":"\u0628\u0639\u0636 \u0627\u0644\u0641\u0627\u0638 \u06a9\u0627 \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0622\u0646\u06d2 \u06a9\u0627 \u0631\u062c\u062d\u0627\u0646\u06d4"},{"term":"Connotation","definition_en":"The feeling or association a word carries beyond its literal meaning.","definition_ur":"\u06a9\u0633\u06cc \u0644\u0641\u0638 \u06a9\u0627 \u0648\u06c1 \u0627\u062d\u0633\u0627\u0633 \u06cc\u0627 \u062a\u0639\u0644\u0642 \u062c\u0648 \u0627\u0633 \u06a9\u06d2 \u0627\u0635\u0644 \u0645\u0639\u0646\u06cc \u0633\u06d2 \u0622\u06af\u06d2 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Communicative grammar","definition_en":"The study of how grammar creates meaning in real communication.","definition_ur":"\u0627\u0633 \u0628\u0627\u062a \u06a9\u0627 \u0645\u0637\u0627\u0644\u0639\u06c1 \u06a9\u06c1 \u06af\u0631\u0627\u0645\u0631 \u062d\u0642\u06cc\u0642\u06cc \u0631\u0627\u0628\u0637\u06d2 \u0645\u06cc\u06ba \u0645\u0639\u0646\u06cc \u06a9\u06cc\u0633\u06d2 \u067e\u06cc\u062f\u0627 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Word formation","definition_en":"The processes by which new words are built from existing parts.","definition_ur":"\u0648\u06c1 \u0639\u0645\u0644 \u062c\u0633 \u06a9\u06d2 \u0630\u0631\u06cc\u0639\u06d2 \u0646\u0626\u06d2 \u0627\u0644\u0641\u0627\u0638 \u0645\u0648\u062c\u0648\u062f\u06c1 \u062d\u0635\u0648\u06ba \u0633\u06d2 \u0628\u0646\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Sentence structure","definition_en":"The way clauses are combined to form sentences.","definition_ur":"\u0648\u06c1 \u0637\u0631\u06cc\u0642\u06c1 \u062c\u0633 \u0633\u06d2 \u062c\u0645\u0644\u0648\u06ba \u06a9\u0648 \u0645\u0644\u06a9\u0631 \u062c\u0645\u0644\u06d2 \u0628\u0646\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Stress","definition_en":"The relative emphasis placed on a syllable within a word.","definition_ur":"\u06a9\u0633\u06cc \u0644\u0641\u0638 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u0634\u062f\u0627\u062f \u067e\u0631 \u062f\u06cc \u06af\u0626\u06cc \u0646\u0633\u0628\u06cc \u062a\u0648\u062c\u06c1\u06d4"},{"term":"Intonation","definition_en":"The rise and fall of the voice across a phrase or sentence.","definition_ur":"\u06a9\u0633\u06cc \u062c\u0645\u0644\u06d2 \u06cc\u0627 \u062c\u0645\u0644\u06d2 \u0645\u06cc\u06ba \u0622\u0648\u0627\u0632 \u06a9\u0627 \u0686\u0691\u06be\u0646\u0627 \u0627\u0648\u0631 \u0627\u062a\u0631\u0646\u0627\u06d4"},{"term":"Phoneme","definition_en":"The smallest unit of sound that can change meaning.","definition_ur":"\u0622\u0648\u0627\u0632 \u06a9\u0627 \u0686\u06be\u0648\u0679\u0627 \u062a\u0631\u06cc\u0646 \u06cc\u0648\u0646\u0679 \u062c\u0648 \u0645\u0639\u0646\u06cc \u0628\u062f\u0644 \u0633\u06a9\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Minimal pair","definition_en":"A pair of words that differ by only one sound.","definition_ur":"\u062f\u0648 \u0627\u0644\u0641\u0627\u0638 \u06a9\u0627 \u0627\u06cc\u06a9 \u062c\u0648\u0691\u0627 \u062c\u0648 \u0635\u0631\u0641 \u0627\u06cc\u06a9 \u0622\u0648\u0627\u0632 \u0633\u06d2 \u0645\u062e\u062a\u0644\u0641 \u06c1\u0648\u06d4"},{"term":"Purpose","definition_en":"Why a text was written.","definition_ur":"\u0645\u062a\u0646 \u06a9\u06cc\u0648\u06ba \u0644\u06a9\u06be\u0627 \u06af\u06cc\u0627\u06d4"},{"term":"Audience","definition_en":"Who the text is written for.","definition_ur":"\u0645\u062a\u0646 \u06a9\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0644\u06a9\u06be\u0627 \u06af\u06cc\u0627\u06d4"},{"term":"Context","definition_en":"The situation in which the text was produced and is being read.","definition_ur":"\u0648\u06c1 \u0635\u0648\u0631\u062a\u062d\u0627\u0644 \u062c\u0633 \u0645\u06cc\u06ba \u062a\u062d\u0631\u06cc\u0631 \u067e\u06cc\u062f\u0627 \u06c1\u0648\u0626\u06cc \u0627\u0648\u0631 \u067e\u0691\u06be\u06cc \u062c\u0627 \u0631\u06c1\u06cc \u06c1\u06d2\u06d4"},{"term":"Tone","definition_en":"The writer\'s attitude toward the subject or the audience.","definition_ur":"\u0645\u0635\u0646\u0641 \u06a9\u0627 \u0645\u0648\u0636\u0648\u0639 \u06cc\u0627 \u0633\u0627\u0645\u0639\u06cc\u0646 \u06a9\u06d2 \u062a\u0639\u0644\u0642 \u06a9\u0627 \u0631\u0648\u06cc\u06c1\u06d4"},{"term":"Bias","definition_en":"A tendency to favour one perspective over others.","definition_ur":"\u0627\u06cc\u06a9 \u0646\u0642\u0637\u06c1 \u0646\u0638\u0631 \u06a9\u0648 \u062f\u0648\u0633\u0631\u06d2 \u067e\u0631 \u062a\u0631\u062c\u06cc\u062d \u062f\u06cc\u0646\u06d2 \u06a9\u0627 \u0631\u062c\u062d\u0627\u0646\u06d4"},{"term":"Stereotype","definition_en":"A fixed, oversimplified belief about a group of people.","definition_ur":"\u06a9\u0633\u06cc \u06af\u0631\u0648\u06c1 \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u0645\u0642\u0631\u0631\u06c1\u060c \u062d\u062f \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u0633\u0627\u062f\u06c1 \u0639\u0642\u06cc\u062f\u06c1\u06d4"},{"term":"Assumption","definition_en":"Something the writer takes for granted without stating it explicitly.","definition_ur":"\u0648\u06c1 \u0686\u06cc\u0632 \u062c\u0633\u06d2 \u0645\u0635\u0646\u0641 \u0628\u063a\u06cc\u0631 \u0648\u0627\u0636\u062d \u0637\u0648\u0631 \u067e\u0631 \u0628\u06cc\u0627\u0646 \u06a9\u06cc\u06d2 \u0639\u0627\u0645 \u0633\u0645\u062c\u06be\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Inference","definition_en":"A conclusion the reader draws from evidence in the text.","definition_ur":"\u0648\u06c1 \u0646\u062a\u06cc\u062c\u06c1 \u062c\u0648 \u0642\u0627\u0631\u06cc \u0645\u062a\u0646 \u06a9\u06d2 \u0634\u0648\u0627\u06c1\u062f \u0633\u06d2 \u0627\u062e\u0630 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Active listening","definition_en":"Listening with the intention to understand, not just to hear.","definition_ur":"\u0633\u0645\u062c\u06be\u0646\u06d2 \u06a9\u06cc \u0646\u06cc\u062a \u0633\u06d2 \u0633\u0646\u0646\u0627\u060c \u0635\u0631\u0641 \u0633\u0646\u0646\u0627 \u0646\u06c1\u06cc\u06ba\u06d4"},{"term":"Critical reading","definition_en":"Reading to evaluate a text, not just understand it.","definition_ur":"\u0645\u062a\u0646 \u06a9\u0648 \u0635\u0631\u0641 \u0633\u0645\u062c\u06be\u0646\u06d2 \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06c1 \u062c\u0627\u0626\u0632\u06c1 \u0644\u06cc\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u067e\u0691\u06be\u0646\u0627\u06d4"},{"term":"Reading strategies","definition_en":"Deliberate approaches to reading that match the reader\'s purpose.","definition_ur":"\u067e\u0691\u06be\u0646\u06d2 \u06a9\u06d2 \u062c\u0627\u0646 \u0628\u0648\u062c\u06be \u06a9\u0631 \u0627\u067e\u0646\u0627\u0626\u06d2 \u06af\u0626\u06d2 \u0637\u0631\u06cc\u0642\u06d2 \u062c\u0648 \u0642\u0627\u0631\u06cc \u06a9\u06d2 \u0645\u0642\u0635\u062f \u0633\u06d2 \u0645\u0645\u0627\u062b\u0644\u062a \u0631\u06a9\u06be\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Skimming","definition_en":"Reading quickly to get the main idea of a text.","definition_ur":"\u0645\u062a\u0646 \u06a9\u0627 \u0628\u0646\u06cc\u0627\u062f\u06cc \u062e\u06cc\u0627\u0644 \u062d\u0627\u0635\u0644 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u062c\u0644\u062f\u06cc \u0633\u06d2 \u067e\u0691\u06be\u0646\u0627\u06d4"},{"term":"Scanning","definition_en":"Reading quickly to find specific information.","definition_ur":"\u0645\u062e\u0635\u0648\u0635 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u062a\u0644\u0627\u0634 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u062c\u0644\u062f\u06cc \u0633\u06d2 \u067e\u0691\u06be\u0646\u0627\u06d4"},{"term":"SQ4R","definition_en":"A structured reading strategy: survey, question, read, recite, review, reflect.","definition_ur":"\u0627\u06cc\u06a9 \u0645\u0646\u0638\u0645 \u067e\u0691\u06be\u0646\u06d2 \u06a9\u06cc \u062d\u06a9\u0645\u062a \u0639\u0645\u0644\u06cc: \u0633\u0631\u0648\u06d2\u060c \u0633\u0648\u0627\u0644\u060c \u067e\u0691\u06be\u0646\u0627\u060c \u062f\u06c1\u0631\u0627\u0646\u0627\u060c \u062c\u0627\u0626\u0632\u06c1\u060c \u063a\u0648\u0631\u06d4"},{"term":"Note-taking","definition_en":"Recording what you hear or read in a way that helps you remember.","definition_ur":"\u062c\u0648 \u0633\u0646\u06cc\u06ba \u06cc\u0627 \u067e\u0691\u06be\u06cc\u06ba \u0627\u0633\u06d2 \u06cc\u0627\u062f \u0631\u06a9\u06be\u0646\u06d2 \u0645\u06cc\u06ba \u0645\u062f\u062f \u062f\u06cc\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0631\u06cc\u06a9\u0627\u0631\u0688 \u06a9\u0631\u0646\u0627\u06d4"},{"term":"Inclusive language","definition_en":"Language that avoids stereotypes, assumptions and gendered terms, and addresses everyone on equal terms.","definition_ur":"\u0648\u06c1 \u0632\u0628\u0627\u0646 \u062c\u0648 \u062a\u0635\u0648\u0631\u06cc\u0627\u062a\u060c \u0641\u0631\u0636\u06cc\u0627\u062a \u0627\u0648\u0631 \u0635\u0646\u0641\u06cc \u0627\u0644\u0641\u0627\u0638 \u0633\u06d2 \u067e\u0631\u06c1\u06cc\u0632 \u06a9\u0631\u06d2 \u0627\u0648\u0631 \u06c1\u0631 \u0634\u062e\u0635 \u06a9\u0648 \u0628\u0631\u0627\u0628\u0631\u06cc \u06a9\u06d2 \u0633\u0627\u062a\u06ba \u062e\u0637\u0627\u0628 \u06a9\u0631\u06d2\u06d4"},{"term":"Cross-cultural communication","definition_en":"Communication between people from different cultural backgrounds, requiring adaptation, listening and suspension of judgement.","definition_ur":"\u0645\u062e\u062a\u0644\u0641 \u062b\u0642\u0627\u0641\u062a\u06cc \u067e\u0633 \u0645\u0646\u0638\u0631 \u06a9\u06d2 \u0644\u0648\u06af\u0648\u06ba \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646 \u0631\u0627\u0628\u0637\u06c1\u060c \u062c\u0633 \u0645\u06cc\u06ba \u0645\u0648\u0627\u0641\u0642\u062a\u060c \u0633\u0646\u0646\u0627 \u0627\u0648\u0631 \u0631\u0627\u0626\u06d2 \u0645\u0639\u0637\u0644 \u06a9\u0631\u0646\u0627 \u0634\u0627\u0645\u0644 \u06c1\u06d2\u06d4"},{"term":"Public speaking","definition_en":"Speaking to a group with a purpose: to inform, persuade or explain.","definition_ur":"\u06a9\u0633\u06cc \u0645\u0642\u0635\u062f \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06af\u0631\u0648\u06c1 \u0633\u06d2 \u06af\u0641\u062a\u06af\u0648 \u06a9\u0631\u0646\u0627: \u0622\u06af\u0627\u06c1 \u06a9\u0631\u0646\u0627\u060c \u0642\u0627\u0626\u0644 \u06a9\u0631\u0646\u0627 \u06cc\u0627 \u0648\u0636\u0627\u062d\u062a \u06a9\u0631\u0646\u0627\u06d4"},{"term":"Stage fright","definition_en":"The intense fear of speaking in front of others, which can be managed through preparation, rehearsal and breathing techniques.","definition_ur":"\u062f\u0648\u0633\u0631\u06d2 \u0644\u0648\u06af\u0648\u06ba \u06a9\u06d2 \u0633\u0627\u0645\u0646\u06d2 \u0628\u0648\u0644\u0646\u06d2 \u06a9\u0627 \u0634\u062f\u06cc\u062f \u062e\u0648\u0641\u060c \u062c\u0648 \u062a\u06cc\u0627\u0631\u06cc\u060c \u0645\u0634\u0642 \u0627\u0648\u0631 \u0633\u0627\u0646\u0633 \u0644\u06cc\u0646\u06d2 \u06a9\u06cc \u062a\u06a9\u0646\u06cc\u06a9 \u0633\u06d2 \u0642\u0627\u0628\u0648 \u06a9\u06cc\u0627 \u062c\u0627 \u0633\u06a9\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Voice modulation","definition_en":"The deliberate variation of volume, pace and pitch to hold attention and convey meaning.","definition_ur":"\u062a\u0648\u062c\u06c1 \u0627\u06a9\u0679\u06be\u06cc \u06a9\u0631\u0646\u06d2 \u0627\u0648\u0631 \u0645\u0645\u0646\u06cc \u067e\u06c1\u0646\u0686\u0627\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0622\u0648\u0627\u0632 \u06a9\u0627 \u062d\u062c\u0645\u060c \u0631\u0641\u062a\u0627\u0631 \u0627\u0648\u0631 \u0644\u06c1\u062c\u06d2 \u062c\u0627\u0646 \u0628\u0648\u062c\u06be \u06a9\u0631 \u0628\u062f\u0644\u0646\u0627\u06d4"},{"term":"Presentation skills","definition_en":"The abilities that let you plan and deliver a clear, engaging talk to a group, from defining purpose to handling questions.","definition_ur":"\u0648\u06c1 \u0635\u0644\u0627\u062d\u06cc\u062a\u06cc\u06ba \u062c\u0648 \u0622\u067e \u06a9\u0648 \u0645\u0642\u0635\u062f \u0645\u062a\u0639\u06cc\u0646 \u06a9\u0631\u0646\u06d2 \u0633\u06d2 \u0644\u06d2 \u06a9\u0631 \u0633\u0648\u0627\u0644\u0627\u062a \u06a9\u0648 \u0633\u0646\u0628\u06be\u0627\u0644\u0646\u06d2 \u062a\u06a9 \u06af\u0631\u0648\u06c1 \u06a9\u0648 \u0648\u0627\u0636\u062d \u0627\u0648\u0631 \u062f\u0644\u06a9\u0634 \u06af\u0641\u062a\u06af\u0648 \u067e\u06cc\u0634 \u06a9\u0631\u0646\u06d2 \u062f\u06cc\u062a\u06cc \u06c1\u06cc\u06ba\u06d4"},{"term":"Handling Q&A","definition_en":"Responding to audience questions confidently, including admitting when you do not know the answer and offering to follow up.","definition_ur":"\u0633\u0627\u0645\u0639\u06cc\u0646 \u06a9\u06d2 \u0633\u0648\u0627\u0644\u0627\u062a \u067e\u0631 \u0627\u0639\u062a\u0645\u0627\u062f \u0633\u06d2 \u062c\u0648\u0627\u0628 \u062f\u06cc\u0646\u0627\u060c \u0628\u0634\u0645\u0648\u0644 \u0627\u0633 \u0628\u0627\u062a \u06a9\u06cc \u062a\u0633\u0644\u06cc\u0645 \u06a9\u0631\u0646\u0627 \u06a9\u06c1 \u0622\u067e \u06a9\u0648 \u062c\u0648\u0627\u0628 \u0646\u06c1\u06cc\u06ba \u0645\u0639\u0644\u0648\u0645 \u0627\u0648\u0631 \u0628\u0639\u062f \u0645\u06cc\u06ba \u0628\u062a\u0627\u0646\u06d2 \u06a9\u06cc \u067e\u06cc\u0634\u06a9\u0634 \u06a9\u0631\u0646\u0627\u06d4"},{"term":"Managing time","definition_en":"Planning how long each section of a presentation will take and sticking to the plan so the talk finishes on time.","definition_ur":"\u067e\u06cc\u0634\u06a9\u0634 \u06a9\u06d2 \u06c1\u0631 \u062d\u0635\u06d2 \u06a9\u0627 \u0648\u0642\u062a \u0637\u06d2 \u06a9\u0631\u0646\u0627 \u0627\u0648\u0631 \u0645\u0646\u0635\u0648\u0628\u06d2 \u067e\u0631 \u0642\u0627\u0626\u0645 \u0631\u06c1\u0646\u0627 \u062a\u0627\u06a9\u06c1 \u06af\u0641\u062a\u06af\u0648 \u0648\u0642\u062a \u067e\u0631 \u062e\u062a\u0645 \u06c1\u0648\u06d4"},{"term":"Informal communication","definition_en":"Unplanned, everyday talk that builds professional relationships, such as small talk, networking and staffroom conversation.","definition_ur":"\u063a\u06cc\u0631 \u0645\u0646\u0638\u0645\u060c \u0631\u0648\u0632\u0645\u0631\u06c1 \u06af\u0641\u062a\u06af\u0648 \u062c\u0648 \u067e\u06cc\u0634\u06c1 \u0648\u0631\u0627\u0646\u06c1 \u0631\u0634\u062a\u06d2 \u0628\u0646\u0627\u062a\u06cc \u06c1\u06d2\u060c \u062c\u06cc\u0633\u06d2 \u06c1\u0644\u06a9\u06cc \u067e\u06be\u0644\u06a9\u06cc \u0628\u0627\u062a \u0686\u06cc\u062a\u060c \u062c\u0627\u0644\u062a \u0627\u0648\u0631 \u0627\u0633\u0627\u062a\u0630\u06c1 \u06a9\u06d2 \u06a9\u0645\u0631\u06d2 \u06a9\u06cc \u06af\u0641\u062a\u06af\u0648\u06d4"},{"term":"Small talk","definition_en":"Brief, light conversation about non-controversial topics, used to build rapport rather than exchange information.","definition_ur":"\u063a\u06cc\u0631 \u0645\u062a\u0646\u0648\u0639 \u0645\u0648\u0636\u0648\u0639\u0627\u062a \u067e\u0631 \u0645\u062e\u062a\u0635\u0631\u060c \u06c1\u0644\u06a9\u06cc \u06af\u0641\u062a\u06af\u0648\u060c \u062c\u0648 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u06a9\u06d2 \u062a\u0628\u0627\u062f\u0644\u06d2 \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06d2 \u062a\u0639\u0644\u0642 \u0628\u0646\u0627\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Networking","definition_en":"Building and maintaining professional relationships through genuine short exchanges that lead to concrete next steps.","definition_ur":"\u062d\u0642\u06cc\u0642\u06cc \u0645\u062e\u062a\u0635\u0631 \u06af\u0641\u062a\u06af\u0648 \u06a9\u06d2 \u0630\u0631\u06cc\u0639\u06d2 \u067e\u06cc\u0634\u06c1 \u0648\u0631\u0627\u0646\u06c1 \u0631\u0634\u062a\u06d2 \u0628\u0646\u0627\u0646\u0627 \u0627\u0648\u0631 \u0628\u0631\u0642\u0631\u0627\u0631 \u0631\u06a9\u06be\u0646\u0627\u060c \u062c\u0648 \u0645\u0644\u0645\u0648\u0633 \u0627\u06af\u0644\u06d2 \u0642\u062f\u0645\u0648\u06ba \u06a9\u06cc \u0637\u0631\u0641 \u0644\u06d2 \u062c\u0627\u0626\u06d2\u06d4"},{"term":"Turn-taking","definition_en":"The convention by which speakers alternate in a conversation, using cues such as pauses and intonation.","definition_ur":"\u0648\u06c1 \u0627\u0635\u0648\u0644 \u062c\u0633 \u06a9\u06d2 \u062a\u062d\u062a \u06af\u0641\u062a\u06af\u0648 \u0645\u06cc\u06ba \u0628\u0648\u0644\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0628\u0627\u0631\u06cc \u0628\u0627\u0631\u06cc \u0628\u0648\u0644\u062a\u06d2 \u06c1\u06cc\u06ba\u060c \u0648\u0642\u0641\u0648\u06ba \u0627\u0648\u0631 \u0644\u06c1\u062c\u06d2 \u06a9\u06cc \u062a\u0628\u062f\u06cc\u0644\u06cc \u062c\u06cc\u0633\u06cc \u0627\u0634\u0627\u0631\u0648\u06ba \u06a9\u06d2 \u0633\u0627\u062a\u06be\u06d4"},{"term":"Conversational repair","definition_en":"What speakers do when something goes wrong in a conversation, such as rephrasing, asking for clarification or checking understanding.","definition_ur":"\u06af\u0641\u062a\u06af\u0648 \u0645\u06cc\u06ba \u06a9\u0686\u06be \u063a\u0644\u0637 \u06c1\u0648\u0646\u06d2 \u067e\u0631 \u0628\u0648\u0644\u0646\u06d2 \u0648\u0627\u0644\u0627 \u06a9\u06cc\u0627 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u060c \u062c\u06cc\u0633\u06d2 \u062f\u0648\u0628\u0627\u0631\u06c1 \u0628\u06cc\u0627\u0646 \u06a9\u0631\u0646\u0627\u060c \u0648\u0636\u0627\u062d\u062a \u0645\u0627\u0646\u06af\u0646\u0627 \u06cc\u0627 \u0633\u0645\u062c\u06be \u06a9\u06cc \u062a\u0635\u062f\u06cc\u0642 \u06a9\u0631\u0646\u0627\u06d4"},{"term":"Politeness strategies","definition_en":"Ways speakers protect each other\'s dignity in interaction, such as indirectness, hedging and showing appreciation.","definition_ur":"\u0648\u06c1 \u0637\u0631\u06cc\u0642\u06d2 \u062c\u0646 \u0633\u06d2 \u0628\u0648\u0644\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u06af\u0641\u062a\u06af\u0648 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06d2 \u0648\u0642\u0627\u0631 \u06a9\u0627 \u062a\u062d\u0641\u0638 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u060c \u062c\u06cc\u0633\u06d2 \u0628\u0627\u0644\u0648\u0627\u0633\u0637\u06c1 \u067e\u0646\u060c \u0627\u062d\u062a\u06cc\u0627\u0637 \u0627\u0648\u0631 \u062a\u0639\u0631\u06cc\u0641 \u062f\u06a9\u06be\u0627\u0646\u0627\u06d4"},{"term":"Business email","definition_en":"A professional writing format used to request, inform, confirm or follow up within or between organisations, following a clear structure: subject line, salutation, opening, body, closing and signature.","definition_ur":"\u067e\u06cc\u0634\u06c1 \u0648\u0631\u0627\u0646\u06c1 \u062a\u062d\u0631\u06cc\u0631 \u06a9\u0627 \u0627\u06cc\u06a9 \u0641\u0627\u0631\u0645\u06cc\u0679 \u062c\u0648 \u062a\u0646\u0638\u06cc\u0645 \u06a9\u06d2 \u0627\u0646\u062f\u0631 \u06cc\u0627 \u062a\u0646\u0638\u06cc\u0645\u0648\u06ba \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646 \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u062f\u06cc\u0646\u06d2\u060c \u0645\u0637\u0644\u0639 \u06a9\u0631\u0646\u06d2\u060c \u062a\u0635\u062f\u06cc\u0642 \u06a9\u0631\u0646\u06d2 \u06cc\u0627 \u0628\u0639\u062f \u0645\u06cc\u06ba \u0631\u0627\u0628\u0637\u06c1 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u060c \u062c\u0633 \u06a9\u06cc \u0648\u0627\u0636\u062d \u0633\u0627\u062e\u062a \u06c1\u0648\u062a\u06cc \u06c1\u06d2: \u0639\u0646\u0648\u0627\u0646\u060c \u0627\u0628\u062a\u062f\u0627\u0626\u06cc\u06c1\u060c \u0627\u063a\u0627\u0632\u060c \u0645\u062a\u0646\u060c \u0627\u062e\u062a\u062a\u0627\u0645 \u0627\u0648\u0631 \u062f\u0633\u062a\u062e\u0637\u06d4"},{"term":"Intercultural communication","definition_en":"The study of how people from different cultural backgrounds communicate with one another, and how cultural assumptions shape the way messages are sent, received and interpreted.","definition_ur":"\u0627\u0633 \u0628\u0627\u062a \u06a9\u0627 \u0645\u0637\u0627\u0644\u0639\u06c1 \u06a9\u06c1 \u0645\u062e\u062a\u0644\u0641 \u062b\u0642\u0627\u0641\u06cc \u067e\u0633 \u0645\u0646\u0638\u0631 \u06a9\u06d2 \u0644\u0648\u06af \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u06cc\u0633\u06d2 \u0631\u0627\u0628\u0637\u06c1 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u060c \u0627\u0648\u0631 \u062b\u0642\u0627\u0641\u06cc \u0645\u0641\u0631\u0648\u0636\u06d2 \u067e\u06cc\u063a\u0627\u0645\u0627\u062a \u06a9\u06d2 \u0628\u06be\u06cc\u062c\u0646\u06d2\u060c \u0648\u0635\u0648\u0644 \u06a9\u0631\u0646\u06d2 \u0627\u0648\u0631 \u0627\u0646 \u06a9\u06cc \u062a\u0641\u0633\u06cc\u0631 \u06a9\u0648 \u06a9\u06cc\u0633\u06d2 \u0634\u06a9\u0644 \u062f\u06cc\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Environmental science","definition_en":"The study of the natural environment and the ways people interact with it.","definition_ur":"\u0642\u062f\u062a\u06cc \u0645\u0627\u062d\u0648\u0644 \u0627\u0648\u0631 \u0627\u0633 \u0633\u06d2 \u0627\u0646\u0633\u0627\u0646\u06cc \u062a\u0639\u0644\u0642 \u06a9\u0627 \u0645\u0637\u0627\u0644\u0639\u06c1\u06d4"},{"term":"Natural environment","definition_en":"Everything around us that is not made by people: air, water, soil, rocks, living things and the climate.","definition_ur":"\u0648\u06c1 \u0633\u0628 \u06a9\u0686\u06be \u062c\u0648 \u06c1\u0645\u0627\u0631\u06d2 \u0627\u0631\u062f \u06af\u0631\u062f \u06c1\u06d2 \u0627\u0648\u0631 \u0627\u0646\u0633\u0627\u0646\u0648\u06ba \u06a9\u0627 \u0628\u0646\u0627\u06cc\u0627 \u06c1\u0648\u0627 \u0646\u06c1\u06cc\u06ba: \u06c1\u0648\u0627\u060c \u067e\u0627\u0646\u06cc\u060c \u0645\u0679\u06cc\u060c \u0686\u0679\u0627\u0646\u06cc\u06ba\u060c \u062c\u0627\u0646\u062f\u0627\u0631 \u0627\u0648\u0631 \u0645\u0648\u0633\u0645\u06d4"},{"term":"Biosphere","definition_en":"The thin zone of the Earth where life exists, where the atmosphere, hydrosphere and lithosphere meet.","definition_ur":"\u0632\u0645\u06cc\u0646 \u06a9\u0627 \u0648\u06c1 \u067e\u062a\u0644\u0627 \u062d\u0635\u06c1 \u062c\u06c1\u0627\u06ba \u0632\u0646\u062f\u06af\u06cc \u067e\u0627\u0626\u06cc \u062c\u0627\u062a\u06cc \u06c1\u06d2\u060c \u062c\u06c1\u0627\u06ba \u06a9\u0631\u06c1 \u06c1\u0648\u0627\u060c \u06a9\u0631\u06c1 \u0622\u0628 \u0627\u0648\u0631 \u06a9\u0631\u06c1 \u062e\u0627\u06a9 \u0622\u067e\u0633 \u0645\u06cc\u06ba \u0645\u0644\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Anthropogenic","definition_en":"Caused by people, especially of environmental change brought about by human activity.","definition_ur":"\u0627\u0646\u0633\u0627\u0646\u0648\u06ba \u06a9\u06d2 \u0633\u0628\u0628 \u067e\u06cc\u062f\u0627 \u06c1\u0648\u0627\u060c \u062e\u0627\u0635 \u0637\u0648\u0631 \u067e\u0631 \u0627\u0646\u0633\u0627\u0646\u06cc \u0633\u0631\u06af\u0631\u0645\u06cc \u0633\u06d2 \u067e\u06cc\u062f\u0627 \u06c1\u0648\u0646\u06d2 \u0648\u0627\u0644\u06cc \u0645\u0627\u062d\u0648\u0644\u06cc\u0627\u062a\u06cc \u062a\u0628\u062f\u06cc\u0644\u06cc \u06a9\u06d2 \u0644\u06cc\u06d2\u06d4"},{"term":"Ecosystem","definition_en":"A living community together with its non-living surroundings, functioning as one system.","definition_ur":"\u062c\u0627\u0646\u062f\u0627\u0631\u0648\u06ba \u06a9\u06cc \u0627\u06cc\u06a9 \u0628\u0631\u0627\u062f\u0631\u06cc \u0627\u0648\u0631 \u0627\u0646 \u06a9\u06d2 \u0628\u06d2 \u062c\u0627\u0646 \u0645\u0627\u062d\u0648\u0644\u060c \u062c\u0648 \u0627\u06cc\u06a9 \u0646\u0638\u0627\u0645 \u06a9\u06cc \u0637\u0631\u062d \u0645\u0644 \u06a9\u0631 \u06a9\u0627\u0645 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Ecosystem services","definition_en":"The benefits people receive from functioning ecosystems, such as clean water, food and protection from storms.","definition_ur":"\u06a9\u0627\u0645 \u06a9\u0631\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0645\u0627\u062d\u0648\u0644\u06cc\u0627\u062a\u06cc \u0646\u0638\u0627\u0645\u0648\u06ba \u0633\u06d2 \u0627\u0646\u0633\u0627\u0646\u0648\u06ba \u06a9\u0648 \u0645\u0644\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0641\u0627\u0626\u062f\u06d2\u060c \u062c\u06cc\u0633\u06d2 \u0635\u0627\u0641 \u067e\u0627\u0646\u06cc\u060c \u062e\u0648\u0631\u0627\u06a9 \u0627\u0648\u0631 \u0637\u0648\u0641\u0627\u0646\u0648\u06ba \u0633\u06d2 \u062d\u0641\u0627\u0638\u062a\u06d4"},{"term":"Natural resources","definition_en":"Anything from the environment that people use to meet their needs, such as water, soil, minerals and forests.","definition_ur":"\u0645\u0627\u062d\u0648\u0644 \u0633\u06d2 \u0645\u0644\u0646\u06d2 \u0648\u0627\u0644\u06cc \u0648\u06c1 \u06c1\u0631 \u0686\u06cc\u0632 \u062c\u0648 \u0627\u0646\u0633\u0627\u0646 \u0627\u067e\u0646\u06cc \u0636\u0631\u0648\u0631\u06cc\u0627\u062a \u067e\u0648\u0631\u06cc \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u060c \u062c\u06cc\u0633\u06d2 \u067e\u0627\u0646\u06cc\u060c \u0645\u0679\u06cc\u060c \u0645\u0639\u062f\u0646\u06cc\u0627\u062a \u0627\u0648\u0631 \u062c\u0646\u06af\u0644\u0627\u062a\u06d4"},{"term":"Renewable resources","definition_en":"Resources that renew themselves on a human timescale if they are not overused.","definition_ur":"\u0648\u06c1 \u0648\u0633\u0627\u0626\u0644 \u062c\u0648 \u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0645\u06cc\u06ba \u0627\u0646\u0633\u0627\u0646\u06cc \u062f\u0648\u0631 \u0645\u06cc\u06ba \u062f\u0648\u0628\u0627\u0631\u06c1 \u067e\u06cc\u062f\u0627 \u06c1\u0648 \u062c\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Non-renewable resources","definition_en":"Resources that exist as fixed stocks and cannot be rebuilt on a human timescale.","definition_ur":"\u0648\u06c1 \u0648\u0633\u0627\u0626\u0644 \u062c\u0648 \u0645\u0642\u0631\u0631\u06c1 \u0645\u0642\u062f\u0627\u0631 \u0645\u06cc\u06ba \u0645\u0648\u062c\u0648\u062f \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u0627\u0646\u0633\u0627\u0646\u06cc \u062f\u0648\u0631 \u0645\u06cc\u06ba \u062f\u0648\u0628\u0627\u0631\u06c1 \u0646\u06c1\u06cc\u06ba \u0628\u0646 \u0633\u06a9\u062a\u06d2\u06d4"},{"term":"Sustainability","definition_en":"The test of whether an action can continue, as it is, without exhausting what it depends on.","definition_ur":"\u0627\u0633 \u0628\u0627\u062a \u06a9\u0627 \u0627\u0645\u062a\u062d\u0627\u0646 \u06a9\u06c1 \u06a9\u0648\u0626\u06cc \u0639\u0645\u0644 \u0627\u0633\u06cc \u0637\u0631\u062d \u062c\u0627\u0631\u06cc \u0631\u06c1 \u0633\u06a9\u062a\u0627 \u06c1\u06d2 \u06cc\u0627 \u0646\u06c1\u06cc\u06ba\u060c \u0628\u063a\u06cc\u0631 \u0627\u0633 \u0686\u06cc\u0632 \u06a9\u0648 \u062e\u062a\u0645 \u06a9\u06cc\u06d2 \u062c\u0633 \u067e\u0631 \u0648\u06c1 \u0645\u0646\u062d\u0635\u0631 \u06c1\u06d2\u06d4"},{"term":"Water security","definition_en":"Reliable access to water of acceptable quality and quantity for health and livelihoods.","definition_ur":"\u0635\u062d\u062a \u0627\u0648\u0631 \u0631\u0648\u0632\u06af\u0627\u0631 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0642\u0627\u0628\u0644\u0650 \u0642\u0628\u0648\u0644 \u0645\u0639\u06cc\u0627\u0631 \u0627\u0648\u0631 \u0645\u0642\u062f\u0627\u0631 \u06a9\u06d2 \u067e\u0627\u0646\u06cc \u062a\u06a9 \u0642\u0627\u0628\u0644\u0650 \u0628\u06be\u0631\u0648\u0633\u06c1 \u0631\u0633\u0627\u0626\u06cc\u06d4"},{"term":"Water scarcity","definition_en":"A situation where per-person water availability falls below the level a population needs, usually measured per year.","definition_ur":"\u0648\u06c1 \u0635\u0648\u0631\u062a\u062d\u0627\u0644 \u062c\u06c1\u0627\u06ba \u0641\u06cc \u0641\u0631\u062f \u067e\u0627\u0646\u06cc \u06a9\u06cc \u062f\u0633\u062a\u06cc\u0627\u0628\u06cc \u0622\u0628\u0627\u062f\u06cc \u06a9\u06cc \u0636\u0631\u0648\u0631\u062a \u0633\u06d2 \u06a9\u0645 \u06c1\u0648 \u062c\u0627\u0626\u06d2\u060c \u0639\u0645\u0648\u0645\u0627\u064b \u0633\u0627\u0644\u0627\u0646\u06c1 \u0645\u0627\u067e\u06cc \u062c\u0627\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Water pollution","definition_en":"The addition of substances or heat to water at a level that harms its use by people or by living things.","definition_ur":"\u067e\u0627\u0646\u06cc \u0645\u06cc\u06ba \u0627\u06cc\u0633\u06d2 \u0645\u0627\u062f\u0648\u06ba \u06cc\u0627 \u062d\u0631\u0627\u0631\u062a \u06a9\u0627 \u0627\u0636\u0627\u0641\u06c1 \u062c\u0648 \u0627\u0633 \u06a9\u06d2 \u0627\u0646\u0633\u0627\u0646\u06cc \u06cc\u0627 \u062d\u06cc\u0627\u062a\u06cc \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646 \u067e\u06c1\u0646\u0686\u0627\u0626\u06d2\u06d4"},{"term":"Pathogen","definition_en":"An organism, such as a bacterium or virus, that causes disease.","definition_ur":"\u06a9\u0648\u0626\u06cc \u062c\u0627\u0646\u062f\u0627\u0631\u060c \u062c\u06cc\u0633\u06d2 \u0628\u06cc\u06a9\u0679\u06cc\u0631\u06cc\u0627 \u06cc\u0627 \u0648\u0627\u0626\u0631\u0633\u060c \u062c\u0648 \u0628\u06cc\u0645\u0627\u0631\u06cc \u067e\u06cc\u062f\u0627 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Eutrophication","definition_en":"The over-fertilisation of a water body by nutrients, causing an algal bloom followed by a collapse in oxygen.","definition_ur":"\u063a\u0630\u0627\u0626\u06cc \u0645\u0627\u062f\u0648\u06ba \u0633\u06d2 \u06a9\u0633\u06cc \u0622\u0628\u06cc \u062c\u0633\u0645 \u06a9\u06cc \u0632\u06cc\u0627\u062f\u06c1 \u06a9\u06be\u0627\u062f \u067e\u0691\u0646\u0627\u060c \u062c\u0633 \u0633\u06d2 \u0627\u0644\u06af\u06cc \u067e\u06be\u06cc\u0644\u062a\u06cc \u06c1\u06d2 \u0627\u0648\u0631 \u067e\u06be\u0631 \u0622\u06a9\u0633\u06cc\u062c\u0646 \u0634\u062f\u06cc\u062f \u06a9\u0645 \u06c1\u0648 \u062c\u0627\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Effluent","definition_en":"The liquid waste a facility or household discharges.","definition_ur":"\u06a9\u0633\u06cc \u0627\u062f\u0627\u0631\u06d2 \u06cc\u0627 \u06af\u06be\u0631 \u0633\u06d2 \u062e\u0627\u0631\u062c \u06c1\u0648\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0645\u0627\u0626\u0639 \u0641\u0636\u0644\u06c1\u06d4"},{"term":"Municipal solid waste","definition_en":"The everyday waste of households, shops, schools and offices.","definition_ur":"\u06af\u06be\u0631\u0648\u06ba\u060c \u062f\u06a9\u0627\u0646\u0648\u06ba\u060c \u0627\u0633\u06a9\u0648\u0644\u0648\u06ba \u0627\u0648\u0631 \u062f\u0641\u062a\u0631\u0648\u06ba \u06a9\u0627 \u0631\u0648\u0632\u0645\u0631\u06c1 \u06a9\u0627 \u06a9\u0686\u0631\u0627\u06d4"},{"term":"Waste hierarchy","definition_en":"The ordering of waste options from best to worst: reduce, reuse, recycle, recover, dispose.","definition_ur":"\u06a9\u0686\u0631\u06d2 \u06a9\u06d2 \u0627\u0646\u062a\u0638\u0627\u0645 \u06a9\u06d2 \u0637\u0631\u06cc\u0642\u0648\u06ba \u06a9\u06cc \u0628\u06c1\u062a\u0631\u06cc\u0646 \u0633\u06d2 \u0628\u062f\u062a\u0631\u06cc\u0646 \u062a\u0631\u062a\u06cc\u0628: \u06a9\u0645 \u06a9\u0631\u06cc\u06ba\u060c \u062f\u0648\u0628\u0627\u0631\u06c1 \u0627\u0633\u062a\u0639\u0645\u0627\u0644\u060c \u0631\u06cc \u0633\u0627\u0626\u06cc\u06a9\u0644\u060c \u0628\u062d\u0627\u0644\u06cc\u060c \u0627\u062e\u0631\u0627\u062c\u06d4"},{"term":"Recycling","definition_en":"Turning used material into new material, which depends on clean, separated collection.","definition_ur":"\u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0634\u062f\u06c1 \u0645\u0627\u062f\u06d2 \u06a9\u0648 \u0646\u06cc\u0627 \u0645\u0648\u0627\u062f \u0628\u0646\u0627\u0646\u0627\u060c \u062c\u0648 \u0635\u0627\u0641 \u0627\u0648\u0631 \u0627\u0644\u06af \u06a9\u06cc\u06d2 \u06af\u0626\u06d2 \u06a9\u0686\u0631\u06d2 \u067e\u0631 \u0645\u0646\u062d\u0635\u0631 \u06c1\u06d2\u06d4"},{"term":"Hazardous waste","definition_en":"Waste whose properties, infectious, toxic, flammable or corrosive, make it dangerous to people or the environment.","definition_ur":"\u0648\u06c1 \u06a9\u0686\u0631\u0627 \u062c\u0633 \u06a9\u06cc \u062e\u0635\u0648\u0635\u06cc\u0627\u062a\u060c \u0639\u062f\u0648\u06cc\u060c \u0632\u06c1\u0631\u06cc\u0644\u06cc\u060c \u0622\u062a\u0634 \u06af\u06cc\u0631 \u06cc\u0627 \u06a9\u0627\u0631\u0622\u0645\u062f\u060c \u0627\u0633\u06d2 \u0627\u0646\u0633\u0627\u0646\u0648\u06ba \u06cc\u0627 \u0645\u0627\u062d\u0648\u0644 \u06a9\u06d2 \u0644\u06cc\u06d2 \u062e\u0637\u0631\u0646\u0627\u06a9 \u0628\u0646\u0627\u062a\u06cc \u06c1\u06cc\u06ba\u06d4"},{"term":"Sanitation","definition_en":"The provision of facilities and services for the safe disposal of human waste, including latrines, sewerage and treatment.","definition_ur":"\u0627\u0646\u0633\u0627\u0646\u06cc \u0641\u0636\u0644\u06d2 \u06a9\u06d2 \u0645\u062d\u0641\u0648\u0638 \u0627\u062e\u0631\u0627\u062c \u06a9\u06cc \u0633\u06c1\u0648\u0644\u06cc\u0627\u062a \u0627\u0648\u0631 \u062e\u062f\u0645\u0627\u062a\u060c \u0628\u0634\u0645\u0648\u0644 \u0628\u06cc\u062a \u0627\u0644\u062e\u0644\u0627\u060c \u06af\u0646\u062f\u06d2 \u067e\u0627\u0646\u06cc \u06a9\u0627 \u0646\u0638\u0627\u0645 \u0627\u0648\u0631 \u0627\u0633 \u06a9\u0627 \u0639\u0644\u0627\u062c\u06d4"},{"term":"Air pollution","definition_en":"The presence of substances in the air at levels that harm people, other living things or materials.","definition_ur":"\u06c1\u0648\u0627 \u0645\u06cc\u06ba \u0627\u06cc\u0633\u06d2 \u0645\u0627\u062f\u0648\u06ba \u06a9\u06cc \u0645\u0648\u062c\u0648\u062f\u06af\u06cc \u062c\u0648 \u0627\u0646\u0633\u0627\u0646\u0648\u06ba\u060c \u062f\u0648\u0633\u0631\u06d2 \u062c\u0627\u0646\u062f\u0627\u0631\u0648\u06ba \u06cc\u0627 \u0686\u06cc\u0632\u0648\u06ba \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646 \u067e\u06c1\u0646\u0686\u0627\u0626\u06d2\u06d4"},{"term":"Noise pollution","definition_en":"Sound loud or persistent enough to harm health or wellbeing.","definition_ur":"\u0627\u06cc\u0633\u06cc \u0622\u0648\u0627\u0632 \u062c\u0648 \u0627\u062a\u0646\u06cc \u0628\u0644\u0646\u062f \u06cc\u0627 \u0645\u0633\u0644\u0633\u0644 \u06c1\u0648 \u06a9\u06c1 \u0635\u062d\u062a \u06cc\u0627 \u0633\u06a9\u0648\u0646 \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646 \u067e\u06c1\u0646\u0686\u0627\u0626\u06d2\u06d4"},{"term":"Hazard","definition_en":"Anything with the potential to cause harm; the condition itself, not the event.","definition_ur":"\u0648\u06c1 \u06c1\u0631 \u0686\u06cc\u0632 \u062c\u0633 \u0645\u06cc\u06ba \u0646\u0642\u0635\u0627\u0646 \u06a9\u06cc \u0635\u0644\u0627\u062d\u06cc\u062a \u06c1\u0648\u061b \u062d\u0627\u0644\u062a \u062e\u0648\u062f\u060c \u0648\u0627\u0642\u0639\u06c1 \u0646\u06c1\u06cc\u06ba\u06d4"},{"term":"Health, safety and environment","definition_en":"The field that studies hazards to people and the environment together, often abbreviated HSE.","definition_ur":"\u0648\u06c1 \u0639\u0644\u0645 \u062c\u0648 \u0627\u0646\u0633\u0627\u0646\u0648\u06ba \u0627\u0648\u0631 \u0645\u0627\u062d\u0648\u0644 \u06a9\u06d2 \u062e\u0637\u0631\u0627\u062a \u06a9\u0648 \u0627\u06cc\u06a9 \u0633\u0627\u062a\u06be \u067e\u0691\u06be\u062a\u0627 \u06c1\u06d2\u060c \u0639\u0627\u0645 \u0637\u0648\u0631 \u067e\u0631 \u0627\u06cc\u0686 \u0627\u06cc\u0633 \u0627\u06cc\u06d4"},{"term":"Environmental safety","definition_en":"Managing the surroundings, a school, worksite, water or air, so that they do not injure the people inside them.","definition_ur":"\u0645\u0627\u062d\u0648\u0644 \u06a9\u0648 \u0627\u06cc\u0633\u06cc \u062d\u0627\u0644\u062a \u0645\u06cc\u06ba \u0631\u06a9\u06be\u0646\u0627\u060c \u0627\u0633\u06a9\u0648\u0644\u060c \u06a9\u0627\u0645 \u06a9\u06cc \u062c\u06af\u06c1\u060c \u067e\u0627\u0646\u06cc \u06cc\u0627 \u06c1\u0648\u0627\u060c \u06a9\u06c1 \u0648\u06c1 \u0627\u0646\u062f\u0631 \u0645\u0648\u062c\u0648\u062f \u0627\u0646\u0633\u0627\u0646\u0648\u06ba \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646 \u0646\u06c1 \u067e\u06c1\u0646\u0686\u0627\u0626\u06d2\u06d4"},{"term":"Risk","definition_en":"The chance and the seriousness of harm actually occurring, in real conditions.","definition_ur":"\u062d\u0642\u06cc\u0642\u06cc \u062d\u0627\u0644\u0627\u062a \u0645\u06cc\u06ba \u0646\u0642\u0635\u0627\u0646 \u06a9\u06d2 \u0648\u0627\u0642\u0639 \u06c1\u0648\u0646\u06d2 \u06a9\u0627 \u0627\u0645\u06a9\u0627\u0646 \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06cc \u0634\u062f\u062a\u06d4"},{"term":"OSH management system","definition_en":"The organised set of elements, policy, organisation, planning, procedures, checking and review, through which a workplace manages its hazards continuously.","definition_ur":"\u0627\u062f\u0627\u0631\u06d2 \u06a9\u06d2 \u0648\u06c1 \u0645\u0646\u0638\u0645 \u0639\u0646\u0627\u0635\u0631\u060c \u067e\u0627\u0644\u06cc\u0633\u06cc\u060c \u062a\u0646\u0638\u06cc\u0645\u060c \u0645\u0646\u0635\u0648\u0628\u06c1 \u0628\u0646\u062f\u06cc\u060c \u0637\u0631\u06cc\u0642\u06c1 \u06a9\u0627\u0631\u060c \u062c\u0627\u0646\u0686 \u0627\u0648\u0631 \u062c\u0627\u0626\u0632\u06c1\u060c \u062c\u0646 \u06a9\u06d2 \u0630\u0631\u06cc\u0639\u06d2 \u06a9\u0627\u0645 \u06a9\u06cc \u062c\u06af\u06c1 \u062e\u0637\u0631\u0627\u062a \u06a9\u0648 \u0645\u0633\u0644\u0633\u0644 \u0633\u0646\u0628\u06be\u0627\u0644\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Incident","definition_en":"Any unplanned event that did or could have caused harm; the injury, the fatality and the near-miss are its grades.","definition_ur":"\u06a9\u0648\u0626\u06cc \u0628\u06be\u06cc \u063a\u06cc\u0631 \u0645\u0646\u0635\u0648\u0628\u06c1 \u0628\u0646\u062f \u0648\u0627\u0642\u0639\u06c1 \u062c\u0633 \u0646\u06d2 \u0646\u0642\u0635\u0627\u0646 \u06a9\u06cc\u0627 \u06c1\u0648 \u06cc\u0627 \u06a9\u0631 \u0633\u06a9\u062a\u0627 \u062a\u06be\u0627\u061b \u0632\u062e\u0645\u060c \u0645\u0648\u062a \u0627\u0648\u0631 \u0628\u0686\u0627 \u0648\u0627\u0642\u0639\u06c1 \u0627\u0633 \u06a9\u06d2 \u062f\u0631\u062c\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Internal control","definition_en":"The measures an organisation uses to make sure its own rules are actually followed: authorisation, records, supervision and review.","definition_ur":"\u0648\u06c1 \u0627\u0642\u062f\u0627\u0645\u0627\u062a \u062c\u0648 \u06a9\u0648\u0626\u06cc \u0627\u062f\u0627\u0631\u06c1 \u0627\u067e\u0646\u06d2 \u0642\u0648\u0627\u0639\u062f \u06a9\u06d2 \u0627\u0635\u0644 \u0645\u06cc\u06ba \u0645\u0627\u0646\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u062a\u0627 \u06c1\u06d2: \u0627\u062c\u0627\u0632\u062a\u060c \u0631\u06cc\u06a9\u0627\u0631\u0688\u060c \u0646\u06af\u0631\u0627\u0646\u06cc \u0627\u0648\u0631 \u062c\u0627\u0626\u0632\u06c1\u06d4"},{"term":"OHS professional","definition_en":"The person a workplace employs to make its safety work: adviser, trainer, inspector, investigator, record keeper and communicator.","definition_ur":"\u0648\u06c1 \u0634\u062e\u0635 \u062c\u0633\u06d2 \u06a9\u0627\u0645 \u06a9\u06cc \u062c\u06af\u06c1 \u062d\u0641\u0627\u0638\u062a \u06a9\u0627 \u06a9\u0627\u0645 \u0633\u0648\u0646\u067e\u062a\u06cc \u06c1\u06d2: \u0645\u0634\u06cc\u0631\u060c \u062a\u0631\u0628\u06cc\u062a \u06a9\u0627\u0631\u060c \u0645\u0639\u0627\u0626\u0646\u06c1 \u06a9\u0627\u0631\u060c \u062a\u0641\u062a\u06cc\u0634 \u06a9\u0627\u0631\u060c \u0631\u06cc\u06a9\u0627\u0631\u0688 \u0631\u06a9\u06be\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0627\u0648\u0631 \u0631\u0627\u0628\u0637\u06c1 \u06a9\u0627\u0631\u06d4"},{"term":"Incident pyramid","definition_en":"The model in which every serious injury sits on a much wider base of minor injuries, near-misses and unsafe acts sharing the same causes.","definition_ur":"\u0648\u06c1 \u0645\u0627\u0688\u0644 \u062c\u0633 \u0645\u06cc\u06ba \u06c1\u0631 \u0633\u0646\u06af\u06cc\u0646 \u0632\u062e\u0645 \u06a9\u06d2 \u0646\u06cc\u0686\u06d2 \u0686\u06be\u0648\u0679\u06d2 \u0632\u062e\u0645\u0648\u06ba\u060c \u0628\u0686\u06d2 \u0648\u0627\u0642\u0639\u0627\u062a \u0627\u0648\u0631 \u063a\u06cc\u0631 \u0645\u062d\u0641\u0648\u0638 \u0639\u0645\u0644 \u06a9\u06cc \u0648\u0633\u06cc\u0639 \u0628\u0646\u06cc\u0627\u062f \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u060c \u0633\u0628 \u0627\u06cc\u06a9 \u06c1\u06cc \u0627\u0633\u0628\u0627\u0628 \u0633\u06d2\u06d4"},{"term":"Swiss cheese model","definition_en":"The model of accident causation in which defences are slices with holes, and harm passes through when the holes line up.","definition_ur":"\u062d\u0627\u062f\u062b\u06d2 \u06a9\u06d2 \u0633\u0628\u0628 \u06a9\u0627 \u0648\u06c1 \u0645\u0627\u0688\u0644 \u062c\u0633 \u0645\u06cc\u06ba \u062f\u0641\u0627\u0639 \u0633\u0648\u0631\u0627\u062e \u0648\u0627\u0644\u06cc \u067e\u0646\u06cc\u0631 \u06a9\u06cc \u0633\u0644\u0627\u0626\u06cc\u06ba \u06c1\u06cc\u06ba\u060c \u0627\u0648\u0631 \u0646\u0642\u0635\u0627\u0646 \u062a\u0628 \u06af\u0632\u0631\u062a\u0627 \u06c1\u06d2 \u062c\u0628 \u0633\u0648\u0631\u0627\u062e \u0627\u06cc\u06a9 \u0644\u0627\u0626\u0646 \u0645\u06cc\u06ba \u0622 \u062c\u0627\u0626\u06cc\u06ba\u06d4"},{"term":"Organizational environment","definition_en":"The workplace\'s own climate: how work is divided, how pressure is applied, and how bad news travels.","definition_ur":"\u06a9\u0627\u0645 \u06a9\u06cc \u062c\u06af\u06c1 \u06a9\u0627 \u0627\u067e\u0646\u0627 \u0645\u0627\u062d\u0648\u0644: \u06a9\u0627\u0645 \u06a9\u06cc \u062a\u0642\u0633\u06cc\u0645\u060c \u062f\u0628\u0627\u0624 \u06a9\u0627 \u0627\u0646\u062f\u0627\u0632\u060c \u0627\u0648\u0631 \u0628\u0631\u06cc \u062e\u0628\u0631 \u06a9\u0627 \u0633\u0641\u0631\u06d4"},{"term":"HSE plan","definition_en":"The document that turns statutes and the PDCA cycle into a named, dated commitment for one workplace.","definition_ur":"\u0648\u06c1 \u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u062c\u0648 \u0642\u0648\u0627\u0646\u06cc\u0646 \u0627\u0648\u0631 \u067e\u06cc \u0688\u06cc \u0633\u06cc \u0627\u06d2 \u0686\u06a9\u0631 \u06a9\u0648 \u06a9\u0633\u06cc \u0627\u06cc\u06a9 \u06a9\u0627\u0645 \u06a9\u06cc \u062c\u06af\u06c1 \u06a9\u06d2 \u0646\u0627\u0645\u0632\u062f\u060c \u062a\u0627\u0631\u06cc\u062e \u0648\u0627\u0644\u06d2 \u0648\u0639\u062f\u06d2 \u0645\u06cc\u06ba \u0628\u062f\u0644\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Toxic agent","definition_en":"A substance that harms a living organism when it reaches a sensitive site in enough amount.","definition_ur":"\u0648\u06c1 \u0645\u0627\u062f\u06c1 \u062c\u0648 \u06a9\u0627\u0641\u06cc \u0645\u0642\u062f\u0627\u0631 \u0645\u06cc\u06ba \u06a9\u0633\u06cc \u062d\u0633\u0627\u0633 \u062c\u06af\u06c1 \u067e\u0631 \u067e\u06c1\u0646\u0686 \u06a9\u0631 \u062c\u0627\u0646\u062f\u0627\u0631 \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646 \u062f\u06cc\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Xenobiotic","definition_en":"Any chemical foreign to the body: pesticides, drugs, industrial solvents, pollutants.","definition_ur":"\u062c\u0633\u0645 \u06a9\u06d2 \u0644\u06cc\u06d2 \u063a\u06cc\u0631 \u0645\u0644\u06a9\u06cc \u06a9\u0648\u0626\u06cc \u0628\u06be\u06cc \u06a9\u06cc\u0645\u06cc\u06a9\u0644: \u06a9\u06cc\u0691\u06d2 \u0645\u0627\u0631 \u0627\u062f\u0648\u06cc\u0627\u062a\u060c \u062f\u0648\u0627\u0626\u06cc\u06ba\u060c \u0635\u0646\u0639\u062a\u06cc \u0633\u0627\u0644\u0648\u06cc\u0646\u0679\u060c \u0622\u0644\u0648\u062f\u06af\u06cc\u0627\u06ba\u06d4"},{"term":"Biotransformation","definition_en":"The liver chemical reworking of a xenobiotic that prepares it for export.","definition_ur":"\u062c\u06af\u0631 \u06a9\u06cc \u0648\u06c1 \u06a9\u06cc\u0645\u06cc\u0627\u0626\u06cc \u062a\u0628\u062f\u06cc\u0644\u06cc \u062c\u0648 \u0632\u06cc\u0646\u0648 \u0628\u0627\u0626\u06cc\u0648\u0679\u06a9 \u06a9\u0648 \u0627\u062e\u0631\u0627\u062c \u06a9\u06d2 \u0644\u06cc\u06d2 \u062a\u06cc\u0627\u0631 \u06a9\u0631\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Detoxification","definition_en":"A biotransformation outcome in which the product is less harmful and exportable.","definition_ur":"\u062d\u06cc\u0627\u062a\u06cc\u0627\u062a\u06cc \u062a\u0628\u062f\u06cc\u0644\u06cc \u06a9\u0627 \u0648\u06c1 \u0646\u062a\u06cc\u062c\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0645\u0635\u0646\u0648\u0639 \u06a9\u0645 \u0646\u0642\u0635\u0627\u0646 \u062f\u06c1 \u0627\u0648\u0631 \u0646\u06a9\u0644\u0646\u06d2 \u06a9\u06d2 \u0642\u0627\u0628\u0644 \u06c1\u0648\u06d4"},{"term":"Bioactivation","definition_en":"A biotransformation outcome in which the product is more poisonous than the original.","definition_ur":"\u062d\u06cc\u0627\u062a\u06cc\u0627\u062a\u06cc \u062a\u0628\u062f\u06cc\u0644\u06cc \u06a9\u0627 \u0648\u06c1 \u0646\u062a\u06cc\u062c\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0645\u0635\u0646\u0648\u0639 \u0627\u0635\u0644 \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u0632\u06c1\u0631\u06cc\u0644\u0627 \u06c1\u0648\u06d4"},{"term":"Multilateral environmental agreement","definition_en":"A treaty among many states that commits them to manage a shared environmental problem, through ratification and reporting cycles.","definition_ur":"\u06a9\u0626\u06cc \u0631\u06cc\u0627\u0633\u062a\u0648\u06ba \u06a9\u0627 \u0648\u06c1 \u0645\u0639\u0627\u06c1\u062f\u06c1 \u062c\u0648 \u0627\u0646\u06c1\u06cc\u06ba \u0645\u0634\u062a\u0631\u06a9\u06c1 \u0645\u0627\u062d\u0648\u0644\u06cc\u0627\u062a\u06cc \u0645\u0633\u0626\u0644\u06d2 \u0633\u0646\u0628\u06be\u0627\u0644\u0646\u06d2 \u06a9\u0627 \u067e\u0627\u0628\u0646\u062f \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u060c \u062a\u0648\u062b\u06cc\u0642 \u0627\u0648\u0631 \u0631\u067e\u0648\u0631\u0679\u0646\u06af \u06a9\u06d2 \u0686\u06a9\u0631 \u06a9\u06d2 \u0630\u0631\u06cc\u0639\u06d2\u06d4"},{"term":"Sustainable Development Goals","definition_en":"Seventeen goals for 2030 adopted by all United Nations member states in 2015, each with targets and indicators.","definition_ur":"\u0633\u062a\u0631\u06c1 \u0627\u06c1\u062f\u0627\u0641 \u0628\u0631\u0627\u0626\u06d2 2030\u060c \u062a\u0645\u0627\u0645 \u0627\u0642\u0648\u0627\u0645 \u0645\u062a\u062d\u062f\u06c1 \u0631\u06a9\u0646 \u0631\u06cc\u0627\u0633\u062a\u0648\u06ba \u0646\u06d2 2015 \u0645\u06cc\u06ba \u0627\u067e\u0646\u0627\u0626\u06d2\u060c \u06c1\u0631 \u0627\u06cc\u06a9 \u0645\u06cc\u06ba \u0646\u0634\u0627\u0646 \u0627\u0648\u0631 \u067e\u06cc\u0645\u0627\u0646\u06d2\u06d4"},{"term":"Toxicology","definition_en":"The study of the adverse effects of chemicals on living organisms.","definition_ur":"\u06a9\u06cc\u0645\u06cc\u06a9\u0644\u0632 \u06a9\u06d2 \u062c\u0627\u0646\u062f\u0627\u0631\u0648\u06ba \u067e\u0631 \u0646\u0642\u0635\u0627\u0646 \u062f\u06c1 \u0627\u062b\u0631\u0627\u062a \u06a9\u0627 \u0639\u0644\u0645\u06d4"},{"term":"Dose","definition_en":"The amount of a substance that reaches a sensitive site; the founding question of toxicology.","definition_ur":"\u06a9\u0633\u06cc \u0645\u0627\u062f\u06d2 \u06a9\u06cc \u0648\u06c1 \u0645\u0642\u062f\u0627\u0631 \u062c\u0648 \u062d\u0633\u0627\u0633 \u062c\u06af\u06c1 \u062a\u06a9 \u067e\u06c1\u0646\u0686\u06d2\u061b \u0632\u06c1\u0631\u06cc\u0644\u06cc \u0645\u0627\u062f\u0648\u06ba \u06a9\u06d2 \u0639\u0644\u0645 \u06a9\u0627 \u0628\u0646\u06cc\u0627\u062f\u06cc \u0633\u0648\u0627\u0644\u06d4"},{"term":"Acute effect","definition_en":"An effect appearing quickly after a single or short exposure.","definition_ur":"\u0627\u06cc\u06a9 \u06cc\u0627 \u0645\u062e\u062a\u0635\u0631 \u0631\u0627\u0628\u0637\u06d2 \u06a9\u06d2 \u0628\u0639\u062f \u062c\u0644\u062f \u0638\u0627\u06c1\u0631 \u06c1\u0648\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0627\u062b\u0631\u06d4"},{"term":"Chronic effect","definition_en":"An effect developing slowly over long, often low-level exposure.","definition_ur":"\u0637\u0648\u06cc\u0644\u060c \u0627\u06a9\u062b\u0631 \u06a9\u0645 \u0633\u0637\u062d \u0631\u0627\u0628\u0637\u06d2 \u067e\u0631 \u0622\u06c1\u0633\u062a\u06c1 \u0622\u06c1\u0633\u062a\u06c1 \u067e\u06cc\u062f\u0627 \u06c1\u0648\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0627\u062b\u0631\u06d4"},{"term":"Genotoxic agent","definition_en":"An agent that damages DNA, the cell instruction manual.","definition_ur":"\u0648\u06c1 \u0639\u0646\u0635\u0631 \u062c\u0648 \u0688\u06cc \u0627\u06cc\u0646 \u0627\u06d2\u060c \u062e\u0644\u06cc\u06d2 \u06a9\u06cc \u06c1\u062f\u0627\u06cc\u062a \u0646\u0627\u0645\u06c1\u060c \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646 \u067e\u06c1\u0646\u0686\u0627\u0626\u06d2\u06d4"},{"term":"Mutagen","definition_en":"An agent that causes changes in the DNA sequence.","definition_ur":"\u0648\u06c1 \u0639\u0646\u0635\u0631 \u062c\u0648 \u0688\u06cc \u0627\u06cc\u0646 \u0627\u06d2 \u06a9\u06cc \u062a\u0631\u062a\u06cc\u0628 \u0645\u06cc\u06ba \u062a\u0628\u062f\u06cc\u0644\u06cc \u067e\u06cc\u062f\u0627 \u06a9\u0631\u06d2\u06d4"},{"term":"Teratogen","definition_en":"An agent that harms the developing unborn child, with timing as decisive as dose.","definition_ur":"\u0648\u06c1 \u0639\u0646\u0635\u0631 \u062c\u0648 \u0628\u0691\u06be\u062a\u06d2 \u06c1\u0648\u0626\u06d2 \u0646\u0627\u062c\u0627\u0626\u0632 \u0628\u0686\u06d2 \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646 \u062f\u06d2\u061b \u0648\u0642\u062a \u062e\u0648\u0631\u0627\u06a9 \u062c\u06cc\u0633\u0627 \u06c1\u06cc \u0641\u06cc\u0635\u0644\u06c1 \u06a9\u0646\u06d4"},{"term":"Carcinogen","definition_en":"An agent that causes cancer.","definition_ur":"\u0648\u06c1 \u0639\u0646\u0635\u0631 \u062c\u0648 \u0633\u0631\u0637\u0627\u0646 \u067e\u06cc\u062f\u0627 \u06a9\u0631\u06d2\u06d4"},{"term":"Sensitizer","definition_en":"An agent that trains the immune system to overreact to later exposures.","definition_ur":"\u0648\u06c1 \u0639\u0646\u0635\u0631 \u062c\u0648 \u0645\u062f\u0627\u0641\u0639\u062a \u06a9\u0648 \u0628\u0639\u062f \u06a9\u06d2 \u0631\u0627\u0628\u0637\u0648\u06ba \u067e\u0631 \u062d\u062f \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u0631\u062f\u0639\u0645\u0644 \u0633\u06a9\u06be\u0627 \u062f\u06d2\u06d4"},{"term":"Essentiality","definition_en":"The property of being required for life, with toxicity waiting higher up the same ladder.","definition_ur":"\u0632\u0646\u062f\u06af\u06cc \u06a9\u06d2 \u0644\u06cc\u06d2 \u0636\u0631\u0648\u0631\u06cc \u06c1\u0648\u0646\u06d2 \u06a9\u06cc \u0635\u0641\u062a\u061b \u0627\u0633\u06cc \u0632\u06cc\u0646\u06d2 \u067e\u0631 \u0627\u0648\u067e\u0631 \u0632\u06c1\u0631\u06cc\u0644\u06cc \u06c1\u0648\u0646\u0627 \u0631\u06a9\u06be\u0627 \u06c1\u06d2\u06d4"},{"term":"Bioaccumulation","definition_en":"The build-up of a substance within one organism when entry outpaces exit.","definition_ur":"\u062c\u0628 \u06a9\u0648\u0626\u06cc \u0645\u0627\u062f\u06c1 \u0627\u0646\u062f\u0631 \u0622\u0646\u0627 \u0628\u0627\u06c1\u0631 \u062c\u0627\u0646\u06d2 \u0633\u06d2 \u062a\u06cc\u0632 \u06c1\u0648 \u062a\u0648 \u0627\u06cc\u06a9 \u062c\u0627\u0646\u062f\u0627\u0631 \u0645\u06cc\u06ba \u062c\u0645\u0639 \u06c1\u0648\u0646\u0627\u06d4"},{"term":"Smog","definition_en":"A visible mixture of pollutants held near the ground: sulfurous in winter, photochemical in summer.","definition_ur":"\u0632\u0645\u06cc\u0646 \u06a9\u06d2 \u0642\u0631\u06cc\u0628 \u0642\u06cc\u062f \u0622\u0644\u0648\u062f\u06af\u06cc\u0648\u06ba \u06a9\u0627 \u062f\u06a9\u06be\u0627\u0626\u06cc \u062f\u06cc\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0645\u0631\u06a9\u0628: \u0633\u0631\u062f\u06cc\u0648\u06ba \u0645\u06cc\u06ba \u0633\u0644\u0641\u0631\u06cc\u060c \u06af\u0631\u0645\u06cc\u0648\u06ba \u0645\u06cc\u06ba \u0641\u0648\u0679\u0648 \u06a9\u06cc\u0645\u06cc\u06a9\u0644\u06d4"},{"term":"Mitigation","definition_en":"Reducing the causes of climate change, emissions and deforestation, for the shared future.","definition_ur":"\u0645\u0648\u0633\u0645\u06cc\u0627\u062a\u06cc \u062a\u0628\u062f\u06cc\u0644\u06cc \u06a9\u06d2 \u0627\u0633\u0628\u0627\u0628 \u06af\u06be\u0679\u0627\u0646\u0627\u060c \u0627\u062e\u0631\u0627\u062c \u0627\u0648\u0631 \u062c\u0646\u06af\u0644\u0627\u062a \u06a9\u0679\u0627\u0626\u06cc\u060c \u0645\u0634\u062a\u0631\u06a9\u06c1 \u0645\u0633\u062a\u0642\u0628\u0644 \u06a9\u06d2 \u0644\u06cc\u06d2\u06d4"},{"term":"Adaptation","definition_en":"Softening the harms of the climate impacts already arriving: heat plans, flood-proofing, early warning.","definition_ur":"\u067e\u06c1\u0646\u0686 \u0686\u0644\u06d2 \u0645\u0648\u0633\u0645\u06cc \u0627\u062b\u0631\u0627\u062a \u06a9\u06d2 \u0646\u0642\u0635\u0627\u0646 \u06a9\u0648 \u0646\u0631\u0645 \u06a9\u0631\u0646\u0627: \u06af\u0631\u0645\u06cc \u0645\u0646\u0635\u0648\u0628\u06d2\u060c \u0633\u06cc\u0644 \u0633\u06d2 \u0628\u0686\u0627\u0624\u060c \u0627\u0628\u062a\u062f\u0627\u0626\u06cc \u0627\u0637\u0644\u0627\u0639\u06d4"},{"term":"Bio-magnification","definition_en":"The rise in concentration of a substance up the food chain as each predator eats many prey.","definition_ur":"\u063a\u0630\u0627\u0626\u06cc \u0632\u0646\u062c\u06cc\u0631 \u067e\u0631 \u0686\u0691\u06be\u062a\u06d2 \u06c1\u0648\u0626\u06d2 \u06a9\u0633\u06cc \u0645\u0627\u062f\u06d2 \u06a9\u06cc \u062d\u0631\u0627\u0633\u062a\u06cc \u0628\u0691\u06be\u0646\u0627\u060c \u062c\u0628 \u06c1\u0631 \u0634\u06a9\u0627\u0631\u06cc \u0628\u06c1\u062a \u0634\u06a9\u0627\u0631 \u06a9\u06be\u0627\u062a\u0627 \u06c1\u06d2\u06d4"}]');var o=i(4848);function a(e){var n=e.term,i=e.children,a=t.find(function(e){return e.term===n}),r=a?"EN: "+a.definition_en+"\nUR: "+a.definition_ur:n;return(0,o.jsx)("abbr",{className:"glossary-term",title:r,"aria-label":r,tabIndex:0,children:null!=i?i:n})}},6606(e,n,i){i.d(n,{A:()=>o});i(6540);var t=i(4848);function o(e){var n=e.label,i=void 0===n?"Print / Save as PDF":n;return(0,t.jsxs)("button",{type:"button",className:"print-handout print-hidden","aria-label":"Print or save this handout as a PDF",onClick:function(){return"undefined"!=typeof window&&window.print()},children:[(0,t.jsx)("span",{"aria-hidden":"true",children:"\ud83d\udda8 "}),i]})}},8453(e,n,i){i.d(n,{R:()=>r,x:()=>s});var t=i(6540);const o={},a=t.createContext(o);function r(e){const n=t.useContext(a);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),t.createElement(a.Provider,{value:n},e.children)}}}]);